SAMPLE_FMT = "<I" + "hhhh" * 3 + "BBhhhH"
SAMPLE_BYTES = struct.calcsize(SAMPLE_FMT)      # 38
assert SAMPLE_BYTES == 38

# Read codes -> (name, kind). kind "w" = 16-bit word, "p" = two bytes.
PARAM_CODES = {
    "D": ("Kp1", "w"), "E": ("Kp2", "w"), "F": ("Kp3", "w"),
    "G": ("Ki1", "w"), "H": ("Ki2", "w"), "I": ("Ki3", "w"),
    "J": ("Kd1", "w"), "K": ("Kd2", "w"), "L": ("Kd3", "w"),
    "M": ("Ks1", "w"), "N": ("Ks2", "w"), "O": ("Ks3", "w"),
    "P": ("PWM1", "p"), "Q": ("PWM2", "p"), "R": ("PWM3", "p"),          # (PWMmin, PWMmax)
    "S": ("LIM1", "p"), "T": ("LIM2", "p"), "U": ("LIM3", "p"),          # (cutoff limit, input clip)
    "V": ("DZ1", "p"), "W": ("DZ2", "p"), "X": ("DZ3", "p"),             # (dead zone, PWMrev)
    "Y": ("STATUS", "p"), "~": ("PWMFREQ", "p"), "$": ("ISRUS", "w"),
    "!": ("FW", "p"),                                                    # (flags, version*10) - firmware 1.4+
    "f": ("FILT", "p"),                                                  # (smoothing shift, max speed/100) - 1.6+
    "l": ("LED", "p"),                                                   # (matrix view, flags) - 1.8+
    "i": ("SENSOR", "p"),                                                # (sensor state, tilt limit) - 1.8+
}
# page 2.9.5 / firmware 2.2.0b1 servo build (SERVO_STEPDIR): asked only of 2.2+ boards - a DC build doesn't answer
SERVO_CODES = {
    "q": ("SERVO", "p"),          # (state: 1 servo build, 2 homed, 4 homing, 8 home switches, 16 servo-on active LOW, 32 servos
                                  #  on, 64 settling, 128 emergency stop pressed; home faults bits 0-2 | to switch on bits 3-5)
    "p": ("STRAVEL", "w"),        # pulses for the whole travel (0..1023)
    "g": ("SACCEL", "w"),         # acceleration limit, 1000 pulses/s^2
    "h": ("SFLAGS", "p"),         # (flags: 1 switches, 2 servo-on active LOW, 4/8/16 motor 1/2/3 reversed, 32 e-stop on A3;
                                  #  inputs open: bits 0-2 home switches, bit 3 the e-stop contact)
}


class Board:
    def __init__(self, cfg):
        self.cfg = cfg
        self.sock = None
        self.stopped = False
        self.page_hold_at = 0.0          # when auto-tune / the full check last renewed [kH] (page 2.7.2)
        self.connected = False
        self.lock = threading.Lock()
        self.slock = threading.Lock()
        self.samples = collections.deque(maxlen=12000)   # 2 minutes at 100 Hz
        self.seq = 0
        self.params = {}
        self.last_rx = 0.0
        self.disconnected_since = time.time()
        self.current_host = None
        self.fw_cache = None
        self.on_connect = None
        self.events = None                   # EventLog (diagnostics)
        self.diag = None                     # last firmware 1.7 diagnostics frame, decoded
        self.diag_seq = 0
        self.imu_info = None                 # 2.9.3: last firmware 2.1.1 "SM3I" frame (the motion sensor link)
        self.imu_info_seq = 0                # (its own count: imu_seq counts the "SM3X" frames - 2.9.3 shared it)
        self.last_dis_cmd = [0.0, 0.0, 0.0]  # when this page last switched each motor off
        self.seat = None                     # firmware 1.9 seat set-up running on the board (from [rdd])
        self.imu = None                      # firmware 1.9 "SM3X": the sensor's acceleration and gyro, latest
        self.imu_seq = 0
        self.ota = None                      # firmware 1.9.2 "SM3U": firmware update state (and the version text)
        self.ota_seq = 0
        self.fw_version = None               # e.g. "1.9.2", from the last "SM3U" frame of this connection
        self.fw_known = None                 # 2.8.1: the last exact version the board reported, on any link
        self.ver_asks = 0                    # [rdu] asked again on this connection (the answer got lost)
        self.ver_ask_at = 0.0
        self.conn_id = 0                     # counts connections, so work for one that already dropped can stop
        self.servo_conn = -1                 # 2.9.5: the connection on which the board answered [rdq] (servo build)
        self.servo_ask_conn = -1             # ... and the one [rdq] was last asked on, when
        self.servo_ask_at = 0.0
        self.connected_at = 0.0
        # page 2.8: the USB cable, through a bridge on the PC it is plugged into (firmware 1.9.5 "USB page mode")
        self.link = "wifi"                   # what self.sock is: "wifi" (the board's TCP port) or "usb" (a bridge)
        self.usb = None                      # the bridge while linked: computer, port, since, telemetry seen, ...
        self.usb_pending = None              # (socket, info, done event) handed over by POST /usb/link
        self.usb_last = None                 # how the last USB link ended (shown in Settings)
        self.usb_refused = {}                # bridge id -> why the page won't take that bridge again
        self.reply_seq = 0                   # counts replies ([rd?] answers), to see the board answering
        self.pending_restore = None          # auto-tune's settings to send again once the board is back (2.8)
        self.usb_want = False                # 2.8.1: the header's switch is on USB (a waiting bridge takes it up)
        self.usb_want_at = 0.0
        self.usb_want_grace = 6.0            # 2.8.2: 70 s after a link that went quiet (network down, no close)
        self.module_reset_at = 0.0           # 2.9: when the page last told the board to restart its USB/WiFi chip
        self.module_resets = 0
        self._mr_key = None                  # 2.9: the last restart report logged (firmware 1.9.8's [rdd] bytes)
        self.standby = None                  # 2.8.1: a bridge waiting with the port closed: id, computer, port, msg, seen
        self.pm = {}                         # 2.9.1: each motor's settings as last read or sent (PWM1, DZ1, LIM1...)
        self.raw = None                      # 2.9.1: the raw pot readings the board saw since raw_mark()

    def start(self):
        """Start connecting - called once everything that reacts to a connection is set up."""
        threading.Thread(target=self._reader, daemon=True).start()

    def _ev(self, kind, msg, **kw):
        if self.events:
            self.events.add(kind, msg, **kw)

    # ---- outgoing ----
    def send(self, data: bytes):
        with self.lock:
            if self.sock:
                try:
                    self.sock.sendall(data)
                    return True
                except OSError:
                    pass
        return False

    def fwnum(self):
        return (self.fw_cache or [0, 0])[1]

    def fw_label(self, diag=None):
        """The firmware version to show (2.8.1). This connection's own text when it has come; until then (just after
        connecting, or switching between WiFi and the cable) the last one the board reported - if it still fits what
        the board says now - rather than the guess from the diagnostics frame (which says "1.9.2" for every 1.9.2+)."""
        fw = self.fw_cache
        if not fw:
            return None
        d = self.diag if diag is None else diag
        if self.fw_version:
            return self.fw_version
        guess = fw_text(fw[1], d)
        k = self.fw_known
        if k and fw[1] == 19 and guess == "1.9.2" and vkey(k) >= (1, 9, 2):
            return k                                     # (a 1.9.2+ board: every one of them reports its version)
        if k and k == guess:
            return k
        return guess

    def _ask_version(self, now):
        """1.9.2+ answers [rdu] with its version text; ask again (a few times) if this connection hasn't had it."""
        if (self.fw_version or self.fwnum() < 19 or not self.diag or "wifi" not in self.diag or self.ver_asks >= 4
                or now - self.connected_at < 6 or now - self.ver_ask_at < 3):
            return
        self.ver_asks += 1
        self.ver_ask_at = now
        self.send(b"[rdu]")

    def trim(self, m):
        """Firmware 1.9 level trim of motor m (added by the board to every position command)."""
        return int(self.seat["trim"][m]) if (self.seat and self.fwnum() >= 19) else 0

    def window(self, m):
        """Where position commands for motor m end up: the SMC3 Clip window and the 1.9 travel limits together."""
        clip = (self.params.get(f"LIM{m + 1}") or [23, 100])[1]
        lo, hi = clip, 1023 - clip
        if self.seat and self.fwnum() >= 19:
            tlo, thi = self.seat["travel"][m]
            if min(hi, thi) >= max(lo, tlo) + 8:
                lo, hi = max(lo, tlo), min(hi, thi)
        return lo, hi

    def centre(self, m):
        """SimHub's centre for motor m: 512, moved by the level trim (firmware 1.9), inside the window."""
        lo, hi = self.window(m)
        return max(lo, min(hi, 512 + self.trim(m)))

    def cmd_word(self, code, value):
        value = int(value)
        if code in ("A", "B", "C") and self.fwnum() >= 19:
            # Firmware 1.9 adds the level trim to every position command. Everything on this page asks for a pot
            # position, so take the trim off again (motor 1 reversed in the firmware: the trim goes the other way).
            m = "ABC".index(code)
            rev = m == 0 and bool((self.fw_cache or [0, 0])[0] & 1)
            value = value + self.trim(m) if rev else value - self.trim(m)
            value = max(0, min(1023, value))
        value = max(0, min(65535, value))
        ok = self.send(b"[" + code.encode() + bytes([value >> 8, value & 0xFF]) + b"]")
        if ok and code in "DEFGHIJKLMNO":                # 2.9.1: the settings mirror (Kp, Ki, Kd, Ks)
            self.pm[PARAM_CODES[code][0]] = value
        return ok

    def seat_field(self, field, value):
        """Firmware 1.9: one seat set-up value ([w] value register, then [k field '='])."""
        v = int(value) & 0xFFFF
        ok = self.send(b"[w" + bytes([v >> 8, v & 0xFF]) + b"]") and self.send(b"[k" + bytes([field & 0xFF]) + b"=]")
        if ok and self.seat and field < 48:          # keep the cache in step until the next [rdd] confirms it
            m, k = field >> 4, field & 15
            val = int(value)
            if k == 0:
                self.seat["trim"][m] = val
            elif k in (1, 2):
                self.seat["travel"][m][k - 1] = val
            elif k in (3, 4):
                self.seat["end_stop"][m][k - 3] = val
        return ok

    def seat_cmd(self, a, b):
        return self.send(b"[k" + bytes([a & 0xFF, b & 0xFF]) + b"]")

    def hold_page(self):
        """Auto-tune and the full check (page 2.7.2, firmware 1.9+): SimHub's position commands wait while they move
        a motor, as during Seat setup and Move motors - [kH 30] (3 s), renewed every second while they run."""
        now = time.time()
        if self.fwnum() >= 19 and now - self.page_hold_at >= 1.0:
            self.seat_cmd(ord("H"), 30)
            self.page_hold_at = now

    def release_page(self):
        if self.page_hold_at:
            self.page_hold_at = 0.0
            if self.connected and self.fwnum() >= 19:
                self.seat_cmd(ord("H"), 0)

    def cmd_pair(self, code, a, b):
        a = max(0, min(255, int(a))); b = max(0, min(255, int(b)))
        ok = self.send(b"[" + code.encode() + bytes([a, b]) + b"]")
        if ok and code in PARAM_CODES and PARAM_CODES[code][1] == "p" and code in "PQRSTUVWX":
            self.pm[PARAM_CODES[code][0]] = [a, b]
        return ok

    def drive(self, m, g_q, f_q, p_q, off):
        """2.9.1: what the board's output stage does with this PID result (SetOutputsMotor, MODE1 and MODE2 alike):
        (signed PWM to the motor, state) - "b" braked (inside the dead zone: the bridge shorts the motor, PWM 0),
        "d" driven (PWMmin added, PWMmax limit), "r" PWMrev past the Clip window, "x" motor switched off. Exact for
        the Q4 numbers in the telemetry, as long as the settings below are the ones running (read or sent by this
        page; SMC3Utils changing them over USB isn't seen until the next read). (None, None) before they are known."""
        if off:
            return 0.0, "x"
        if self.servo_conn == self.conn_id:          # 2.9.5 servo build: the planned speed (255 = 20 000 pulses/s)
            return p_q / 16.0, "s"
        n = m + 1
        pw, dz, lim = self.pm.get(f"PWM{n}"), self.pm.get(f"DZ{n}"), self.pm.get(f"LIM{n}")
        if not pw or not dz:
            return None, None
        pmin, pmax = pw[0] << 4, pw[1] << 4
        dzq, rev = dz[0] << 4, dz[1] << 4
        if rev and lim:                          # (not while creeping back after power-up - rare, not in telemetry)
            if f_q > (1023 - lim[1]) << 4:
                return -rev / 16.0, "r"
            if f_q < lim[1] << 4:
                return rev / 16.0, "r"
        if g_q > f_q + dzq or g_q < f_q - dzq:
            out = min(p_q + pmin, pmax) if p_q >= 0 else -min(-p_q + pmin, pmax)
            return out / 16.0, "d"
        return 0.0, "b"

    def raw_mark(self, base=None):
        """2.9.1: start collecting the board's raw pot readings ([rdd]: lowest, highest and biggest single-cycle
        change at 4 kHz, before the glitch filter - each [rdd] starts them again, so every frame from now on is
        folded in, whoever asked for it). `base` is the [rdd] asked for just before: it starts the board's own
        range again here, and its glitch counts are where the counting starts."""
        g0 = [x["pot_glitches"] for x in (base or {}).get("motors") or []] or [None, None, None]
        self.raw = {"t0": time.time(), "frames": 0, "m": [None, None, None], "g0": g0}

    def _raw_fold(self, d):
        r = self.raw
        if not r:
            return
        r["frames"] += 1
        for m, x in enumerate(d.get("motors") or []):
            a = r["m"][m]
            if a is None:
                g0 = r["g0"][m] if m < len(r["g0"]) and r["g0"][m] is not None else x["pot_glitches"]
                r["m"][m] = {"min": x["pot_min"], "max": x["pot_max"], "step": x["pot_biggest_step"],
                             "glitches0": g0, "glitches": x["pot_glitches"]}
            else:
                a["min"], a["max"] = min(a["min"], x["pot_min"]), max(a["max"], x["pot_max"])
                a["step"] = max(a["step"], x["pot_biggest_step"])
                a["glitches"] = x["pot_glitches"]

    def cmd_text(self, text3):
        if text3 == "dis":
            self.last_dis_cmd = [time.time()] * 3
        elif len(text3) == 3 and text3[:2] == "di" and text3[2] in "123":
            self.last_dis_cmd[int(text3[2]) - 1] = time.time()
        return self.send(b"[" + text3.encode()[:3] + b"]")

    def read_diag(self, timeout=1.5):
        """Firmware 1.7: ask for one diagnostics frame and wait for it."""
        if (self.fw_cache or [0, 0])[1] < 17 or not self.connected:
            return None
        seq0 = self.diag_seq
        self.send(b"[rdd]")
        end = time.time() + timeout
        while time.time() < end:
            if self.diag_seq != seq0:
                return dict(self.diag)
            time.sleep(0.02)
        return None

    def imu_info_ok(self):
        """2.9.3: does the board answer [rdj] with its sensor link ("SM3I", firmware 2.1.1 and newer)?"""
        k = self.fw_known or self.fw_version
        return bool(k) and self.fwnum() >= 21 and vkey(k) >= vkey("2.1.1b1")

    def read_imu_info(self, timeout=1.0):
        """2.9.3 / firmware 2.1.1: ask for the motion sensor link frame and wait for it (None if it doesn't come)."""
        if not self.connected or not self.imu_info_ok():
            return None
        seq0 = self.imu_info_seq
        self.send(b"[rdj]")
        end = time.time() + timeout
        while time.time() < end:
            if self.imu_info_seq != seq0 and self.imu_info:
                return dict(self.imu_info)
            time.sleep(0.02)
        return None

    def board_settings(self, timeout=1.5):
        """Firmware 1.8: LED matrix and motion sensor settings and state, from one diagnostics frame."""
        if (self.fw_cache or [0, 0])[1] < 18:
            return None
        d = self.read_diag(timeout)
        if not d or "sensor" not in d:
            return None
        return {"sensor": d["sensor"], "matrix": d["matrix"], "saved": decode_board_block(d["eeprom"]),
                "seat": d.get("seat"), "soft_start": d.get("soft_start")}

    def ping(self, timeout=1.5):
        """Round trip of one read command in ms (firmware 1.4+), None if no answer."""
        self.params.pop("FW", None)
        t0 = time.time()
        self.send(b"[rd!]")
        while time.time() - t0 < timeout:
            if "FW" in self.params:
                return round((time.time() - t0) * 1000)
            time.sleep(0.005)
        return None

    def read_params(self, timeout=2.0):
        for name, _ in PARAM_CODES.values():
            self.params.pop(name, None)
        for code in PARAM_CODES:
            self.send(b"[rd" + code.encode() + b"]")
            time.sleep(0.03)
        deadline = time.time() + timeout
        expected = len(PARAM_CODES) - 4          # "!" (1.4+), "f" (1.6+), "l" and "i" (1.8+) are missing on older firmware
        fw = self.fwnum()                         # known firmware: stop as soon as everything it can answer is in
        need = (len(PARAM_CODES) - (fw < 14) - (fw < 16) - 2 * (fw < 18)) if fw else None
        while time.time() < deadline and len(self.params) < len(PARAM_CODES):
            if need is not None and len(self.params) >= need:
                break
            if len(self.params) >= expected and time.time() > deadline - timeout + 1.0:
                break
            time.sleep(0.05)
        return dict(self.params)

    def reconnect(self):
        if self.link != "usb":                       # the address only matters again once the USB link ends
            self._drop()

    # ---- the USB cable (page 2.8, firmware 1.9.5) ----
    def attach_usb(self, sock, info):
        """A bridge on the PC with the USB cable connected (POST /usb/link). The reader takes it over from WiFi. Returns
        an event that is set once the link has ended (the request's thread waits for it)."""
        done = threading.Event()
        with self.lock:
            old, self.usb_pending = self.usb_pending, (sock, info, done)
        if old:
            old[2].set()
        return done                                  # the reader thread makes the switch (it owns every switch)

    def detach_usb(self, why, refuse=False):
        """End the USB link from the page (Back to WiFi, or a board that can't do it). refuse: that bridge gets this
        reason if it tries again."""
        with self.lock:
            pend, self.usb_pending = self.usb_pending, None
        if pend:                                     # one still waiting to be taken: turn it away too
            if refuse and pend[1].get("id"):
                self.usb_refused[pend[1]["id"]] = why
            pend[2].set()
        u = self.usb
        if self.link != "usb" or not u:
            return bool(pend)
        if refuse and u.get("id"):
            self.usb_refused[u["id"]] = why
        u["end"] = why
        self.send(b"[kU\x00]")                       # the board goes back to WiFi at once (not 5 s later)
        self._drop()
        return True

    def reboot_ok(self):
        """2.9 / firmware 2.0 (2.0b2 on): can the page restart this board ([kZ 'R'])?"""
        k = self.fw_known or self.fw_version
        return bool(k) and vkey(k) >= vkey("2.0b2")

    def simhub_driving(self):
        """SimHub sent a position command less than 10 s ago (from a fresh diagnostics frame), or None if unknown."""
        d = self.read_diag(0.8) if self.connected else None
        if not d:
            return None
        ms = d.get("ms_since_usb_target")
        return ms is not None and ms < 10000

    def reboot(self):
        """[kZ 'R']: the board switches its motors off and restarts, as with its RESET button. The connection drops and
        the page reconnects by itself (WiFi in a few seconds; on the cable the browser relinks when the port is back)."""
        if not self.connected:
            return False, "The page isn't connected to the board."
        if not (self.fw_known or self.fw_version):
            return False, "The board hasn't told the page its firmware version yet - try again in a few seconds."
        if not self.reboot_ok():
            return False, ("The board's firmware can't restart on request - that needs firmware 2.0. Press the board's "
                           "RESET button instead.")
        if self.simhub_driving():
            return False, ("SimHub is sending positions to the board (a game is running) - stop SimHub's motion output "
                           "first, then restart the board.")
        self.send(b"[kZR]")                          # (over WiFi or the page's USB link, whichever is up)
        log("board restart asked by the page ([kZ R])")
        self._ev("link", "The page asked the board to restart (the motors switch off, the board comes back in a few "
                 "seconds and soft-starts to its targets).", quiet=False)
        return True, "restarting"

    def usb_owner(self):
        """2.9 / firmware 2.0: who has the board's USB connector. From the build flags ([rdd], or [rd!]): bit 6 = the
        main chip has it now (native port), bit 7 = that is the saved setting. None when the board can't say."""
        k = self.fw_known or self.fw_version
        if not (k and vkey(k) >= (2, 0, 0)):
            return None
        fl = None
        if self.connected and (not self.diag or time.time() - self.diag.get("rx", 0) > 3) and \
                time.time() - getattr(self, "_owner_read_at", 0) > 3:
            self._owner_read_at = time.time()           # a fresh frame: the owner can change at any moment ([kO])
            self.read_diag(0.8)
        if self.diag and isinstance(self.diag.get("build"), int):
            fl = self.diag["build"]
        elif self.fw_cache:
            fl = self.fw_cache[0]
        if fl is None:
            return {"known": False}
        return {"known": True, "native": bool(fl & 64), "saved_native": bool(fl & 128)}

    def usb_native(self):
        o = self.usb_owner()
        return bool(o and o.get("native"))

    def set_usb_owner(self, mode):
        """[kO n]: 0 = the WiFi chip (saved), 1 = the main chip (saved), 2 = the WiFi chip until the next reset. The port
        on the PC changes at once, so a USB link of ours ends here; the board stays on WiFi as it was."""
        if self.usb_owner() is None:
            return False, "The board's firmware can't move its USB port (that needs firmware 2.0)."
        if not self.connected:
            return False, "The page isn't connected to the board."
        what = {0: "the WiFi chip (saved)", 1: "the main chip (saved)", 2: "the WiFi chip until the board's next reset"}[mode]
        if self.link == "usb":
            self.send(b"[kO" + bytes([mode]) + b"]")
            time.sleep(0.05)
            self.detach_usb(f"The board's USB port was handed to {what}: it comes back on the PC as another port (a new "
                            "COM number); pick it in the browser once more, or point the bridge / SimHub at it.")
        else:
            self.send(b"[kO" + bytes([mode]) + b"]")
        log(f"USB port owner -> {what} ([kO {mode}])")
        self._ev("link", f"The board's USB port was handed to {what}. On the PC it is another COM port from now on "
                 "(SimHub and the bridge need the new one; the browser asks which port once).", quiet=False)
        return True, what

    def driver_info(self, fresh=False):
        """2.9.5 / firmware 2.1.2: which kind of motor driver the board drives. [rd!] flags bit1: set = IBT-2 /
        BTS7960 (what MODE2 built), clear = PWM + direction (MODE1). Firmware 2.1.2 makes it a setting ([kD n])."""
        k = self.fw_known or self.fw_version
        if fresh and self.connected:
            self.ping(1.0)
        fl = self.fw_cache[0] if self.fw_cache else None
        if fl is None and self.diag and isinstance(self.diag.get("build"), int):
            fl = self.diag["build"]
        return {"known": fl is not None, "type": None if fl is None else (0 if fl & 2 else 1),
                "settable": bool(k) and vkey(k) >= (2, 1, 2), "firmware": k}

    def set_driver_type(self, n):
        """[kD n]: 0 = IBT-2 / BTS7960, 1 = PWM + direction. The board takes it only with all three motors off and
        SimHub not sending positions; it saves it at once."""
        if not self.connected:
            return False, "The page isn't connected to the board."
        info = self.driver_info()
        if not info["settable"]:
            return False, ("Choosing the driver here needs firmware 2.2.0b1 or newer (the beta in All firmware). With older "
                           "firmware, build the sketch with #define MODE2 (IBT-2) or #define MODE1 (PWM + direction).")
        if self.simhub_driving():
            return False, ("SimHub is sending positions to the board (a game is running) - stop SimHub's motion output "
                           "first.")
        st = self.latest()
        if not st or not all(st["dis"][m] for m in range(3)):
            return False, ("Switch the motors off first (Disable Motors): the board changes the driver type only with "
                           "all three off.")
        self.send(b"[kD" + bytes([48 + n]) + b"]")
        time.sleep(0.25)
        self.ping(1.0)
        info = self.driver_info()
        what = "PWM + direction" if n else "IBT-2 / BTS7960"
        if info["type"] != n:
            return False, "The board didn't confirm the change - try again in a few seconds."
        log(f"motor driver type -> {what} ([kD {n}])")
        self._ev("link", f"The board now drives {what} motor drivers (saved on the board). Wire them as Electronics, "
                 "Signal wiring shows before switching the motors on.", quiet=False)
        return True, what

    # ---- page 2.9.5 / firmware 2.2.0b1: the servo (step / direction) build ----
    def is_servo(self):
        """True: this connection's board runs the servo build (it answered [rdq]); False: it doesn't (older than 2.2,
        or a 2.2 DC build that didn't answer); None: not known yet."""
        k = self.fw_known or self.fw_version
        if not k:
            return None
        if vkey(k) < (2, 2):
            return False
        if self.servo_conn == self.conn_id:
            return True
        if self.servo_ask_conn == self.conn_id and time.time() - self.servo_ask_at > 2.0:
            return False
        return None

    def servo_info(self, fresh=False):
        """The servo build's state and settings ([rdq] [rdp] [rdg] [rdh])."""
        k = self.fw_known or self.fw_version
        if (fresh and self.connected and k and vkey(k) >= (2, 2)
                and (self.is_servo() is not False or time.time() - self.servo_ask_at > 30)):   # (a DC build: not every time)
            for name, _ in SERVO_CODES.values():
                self.params.pop(name, None)
            self.servo_ask_conn, self.servo_ask_at = self.conn_id, time.time()
            self.send(b"[rdq][rdp][rdg][rdh]")
            t0 = time.time()
            while time.time() - t0 < 1.0 and "SFLAGS" not in self.params:
                time.sleep(0.02)
            if "SERVO" not in self.params:
                self.servo_ask_at = time.time() - 2.5          # asked and no answer: not a servo build
        sv = self.is_servo()
        info = {"servo": sv, "firmware": k, "connected": self.connected}
        q, h = self.params.get("SERVO"), self.params.get("SFLAGS")
        if sv and q:
            a, f = q
            info.update(homed=bool(a & 2), homing=bool(a & 4), settling=bool(a & 64), switches=bool(a & 8),
                        son_low=bool(a & 16), son=bool(a & 32), estop=bool(a & 128), fault=[bool((f >> m) & 1) for m in range(3)],
                        want=[bool((f >> (3 + m)) & 1) for m in range(3)])
        if sv:
            info["travel"] = self.params.get("STRAVEL")
            info["accel"] = self.params.get("SACCEL")
            if h:
                info["flags"] = h[0]
                info["reversed"] = [bool((h[0] >> (2 + m)) & 1) for m in range(3)]
                info["inputs_open"] = [bool((h[1] >> m) & 1) for m in range(3)]
                info["estop_input"] = bool(h[0] & 32)
                info["estop_open"] = bool(h[1] & 8)
        return info

    def servo_set(self, travel=None, accel=None, flags=None):
        """Fields 83 (travel pulses), 84 (acceleration) and 86 (flags); the board saves them at once. Travel and flags
        only with every motor off."""
        if not self.connected:
            return False, "The page isn't connected to the board."
        if self.is_servo() is not True:
            return False, "The board doesn't run the servo firmware (SMC3_R4_Servo 2.2.0b1)."
        st = self.latest()
        off = bool(st and all(st["dis"][m] for m in range(3)))
        if (travel is not None or flags is not None) and not off:
            return False, "Switch the motors off first (Disable Motors): travel and wiring settings change only with all three off."
        if travel is not None:
            self.seat_field(83, int(travel))
        if accel is not None:
            self.seat_field(84, int(accel))
        if flags is not None:
            self.seat_field(86, int(flags))
        time.sleep(0.25)
        info = self.servo_info(fresh=True)
        bad = [n for n, v, got in (("travel", travel, info.get("travel")), ("acceleration", accel, info.get("accel")),
                                   ("wiring", flags, info.get("flags"))) if v is not None and int(v) != got]
        if bad:
            return False, "The board didn't take the " + " and ".join(bad) + " - check the values and try again."
        log(f"servo settings -> travel {info.get('travel')} pulses, acceleration {info.get('accel')}, flags {info.get('flags')}")
        self._ev("link", "Servo settings saved on the board.", quiet=False)
        return True, info

    def servo_home(self):
        """[kG1]: release the servos and home again (bottom: they settle for 4 s first; switches: they drive to them)."""
        if not self.connected:
            return False, "The page isn't connected to the board."
        if self.is_servo() is not True:
            return False, "The board doesn't run the servo firmware."
        if self.simhub_driving():
            return False, "SimHub is sending positions to the board (a game is running) - stop SimHub's motion output first."
        st = self.latest()
        if not st or not all(st["dis"][m] for m in range(3)):
            return False, "Switch the motors off first (Disable Motors)."
        if self.servo_info(fresh=True).get("estop"):
            return False, "The emergency stop is pressed - release it first."
        self.send(b"[kG1]")
        time.sleep(0.25)
        info = self.servo_info(fresh=True)
        if not info.get("homing"):
            return False, "The board didn't start homing - try again in a few seconds."
        log("servo homing started ([kG1])")
        self._ev("link", "Servos released and homing again" + (" (they settle at the bottom for 4 s first)."
                                                              if not info.get("switches") else " (driving to the home switches)."),
                 quiet=False)
        return True, info

    def module_reset_ok(self):
        """2.9: can this board restart its USB/WiFi chip on request (firmware 1.9.7; done right from 1.9.8). Not on a
        native USB port (firmware 2.0: the WiFi chip isn't in the USB path)."""
        k = self.fw_known or self.fw_version
        return bool(k) and vkey(k) >= (1, 9, 7) and not self.usb_native()

    def module_reset_now(self):
        """2.9: the board's USB output is stalled right now (nothing came back when a port was opened): ask it to restart
        its USB chip over whatever link is up. False when it can't: firmware older than 1.9.7, not connected, or done
        less than a minute ago."""
        if not self.module_reset_ok() or not self.connected or time.time() - self.module_reset_at < 60:
            return False
        self.module_reset_at = time.time()
        self.module_resets += 1
        self.send(b"[kE\x01]")
        log("USB stall (nothing comes back over the cable): asked the board to restart its USB/WiFi chip ([kE1])")
        self._ev("link", "Nothing comes back from the board over the USB cable (the UNO R4 WiFi's USB output dies now and "
                 "then). The page asked it to restart its USB/WiFi chip; " + self.module_after_text(), quiet=False)
        return True

    def module_resetting(self):
        """True for a moment after the page asked the board to restart its USB chip: the port is about to go away
        and come back, so a link now would only die again. (2.9: 3 s, was 8 - the port is back by then and the
        board answers at once on firmware 1.9.8.)"""
        return time.time() - self.module_reset_at < 3.0

    def module_after_text(self):
        """2.9: what follows the chip restart, for the firmware the board runs."""
        k = self.fw_known or self.fw_version
        if k and vkey(k) >= (1, 9, 8):
            return ("the port comes back in a few seconds and the cable link follows by itself; the board rejoins WiFi "
                    "once the page leaves the cable (or after 25 s).")
        return ("the port comes back in a few seconds. On firmware 1.9.7 the board then gets stuck retrying WiFi (its "
                "matrix crawls, nothing answers): press the board's RESET button. Firmware 2.0 fixes this.")

    def _module_report(self, mr):
        """2.9: firmware 1.9.8 reports how its last chip restart went in every [rdd] frame: log it once per restart,
        and once more when the WiFi outcome changes (the first frame often comes over the cable, before WiFi)."""
        if not mr.get("count") or mr.get("age_s") is None or mr["age_s"] > 600:
            return
        if not mr.get("chip_back_s") and mr["age_s"] < 15:     # too early to say anything (the chip boots for 5 s)
            return
        key = (mr["count"], bool(mr.get("chip_back_s")), mr.get("wifi_last_code"))
        if key == self._mr_key:
            return
        self._mr_key = key
        back = mr.get("chip_back_s")
        txt = f"USB/WiFi chip restart #{mr['count']} ({mr['age_s']} s ago): "
        txt += f"the chip answered again after {back} s" if back else "the chip hasn't answered the board yet"
        txt += f"; WiFi {mr.get('wifi_last')}"
        if mr.get("wifi_tries"):
            txt += f" after {mr['wifi_tries']} tr{'y' if mr['wifi_tries'] == 1 else 'ies'}"
        if self.link == "usb" and not mr.get("wifi_last_code"):
            txt += " (the page is on the cable, so WiFi waits)"
        txt += "."
        log(txt)
        self._ev("link", "The board says: " + txt, quiet=True)

    def _module_reset(self, u):
        """The board went quiet on the cable while the PC's commands still reach it: the UNO R4 WiFi's USB output has
        died (a known board problem - only re-enumerating clears it). With firmware 1.9.7+ the page sends [kE1] down
        the stalled link: the board restarts its USB/WiFi chip, the port comes back as after a replug and the browser
        or bridge links again by itself. WiFi rejoins a few seconds later. At most once a minute."""
        if not self.module_reset_ok():
            if self.usb_native():
                u["end"] += (" (This board's USB port is the main chip's own - firmware 2.0 - so this isn't the WiFi "
                             "chip's known stall: check the cable, and that no other program has the port.)")
            else:
                u["end"] += (" The UNO R4 WiFi's USB output dies like this now and then; unplug the USB cable and plug it "
                             "back in. Firmware 2.0 takes the WiFi chip out of the USB path, so this doesn't happen "
                             "any more.")
            return
        if time.time() - self.module_reset_at < 60:
            u["end"] += " (The board's USB chip was restarted less than a minute ago; not again yet.)"
            return
        self.module_reset_at = time.time()
        self.module_resets += 1
        self.send(b"[kE\x01]")
        time.sleep(0.05)
        u["end"] += (" The page asked the board to restart its USB chip, which clears this (a known UNO R4 WiFi "
                     "problem): " + self.module_after_text())
        log("USB stall: asked the board to restart its USB/WiFi chip ([kE1])")
        self._ev("link", "The board went quiet on the USB cable (the UNO R4 WiFi's USB output dies now and then). The "
                 "page asked it to restart its USB/WiFi chip; " + self.module_after_text(), quiet=False)

    def bridge_waiting(self):
        """2.8.1: the bridge that asked within the last 4 s whether the page wants the cable (port closed meanwhile)."""
        sb = self.standby
        return sb if sb and time.time() - sb["seen"] < 4.0 else None

    def want_usb(self):
        """The switch's position: on (USB) while linked, or while asked for and a bridge is there to take it up."""
        if self.link == "usb" and self.usb:
            return True
        if (self.usb_want and not self.bridge_waiting() and not self.usb_pending
                and time.time() - self.usb_want_at > self.usb_want_grace):
            self.usb_want = False                        # nobody took it up (the bridge window was closed)
        return self.usb_want

    def link_info(self):
        u = self.usb
        sb = self.bridge_waiting()
        bridge = ({"computer": sb.get("computer"), "port": sb.get("port"), "msg": sb.get("msg") or ""} if sb else None)
        if self.link == "usb" and u:
            return {"kind": "usb", "computer": u.get("computer"), "port": u.get("port"), "since": u.get("since"),
                    "age": round(time.time() - u["since"], 1), "streaming": bool(u.get("tel_at")),
                    "bridge": u.get("version"), "want": True, "waiting": None}
        return {"kind": "wifi", "host": self.current_host, "want": self.want_usb(), "waiting": bridge}

    def _take_usb(self):
        with self.lock:
            pend, self.usb_pending = self.usb_pending, None
        if not pend:
            return False
        sock, info, done = pend
        now = time.time()
        self.standby = None                              # (it isn't waiting any more)
        with self.lock:
            self.sock = sock
            self.link = "usb"
            self.usb = dict(info, since=now, done=done, tel_at=None, ka_at=0.0, reply0=self.reply_seq, end=None,
                            last_ms=None)
        self.conn_id += 1
        self.connected_at = now
        self.connected = True
        self.last_rx = now
        self.fw_version = None
        self.ver_asks = 0
        self._keepalive(now)
        where = f"{info.get('computer') or 'the PC'}, {info.get('port') or 'its USB port'}"
        log(f"connected to the board over the USB cable ({where})")
        self._ev("link", f"Connected to the board over the USB cable ({where}). WiFi rests meanwhile.", quiet=True)
        if self.on_connect:
            threading.Thread(target=self.on_connect, daemon=True).start()
        return True

    def _keepalive(self, now):
        """[kU1] keeps the board in USB page mode (it ends 5 s after the last one) - 2.8.3: twice a second (was once),
        so a damaged one (firmware 1.9.5 loses bytes on the USB port now and then) doesn't end it."""
        u = self.usb
        if u and now - u["ka_at"] >= 0.5:
            u["ka_at"] = now
            self.send(b"[kU\x01]")

    def _usb_stream(self, u, ms):
        """Telemetry arrived over the cable. The first time, or when the board restarted meanwhile (its clock went
        back - a board that resets when the port opens), read the board's settings again: over WiFi a restart is a
        new connection, over the cable it isn't."""
        now = time.time()
        again = False
        if not u["tel_at"]:
            u["tel_at"] = now
            self._ev("link", "The board streams over the USB cable (firmware 1.9.5 USB page mode).", quiet=True)
            again = now - u["since"] > 2.5               # it wasn't streaming at once: it was starting, and what the
                                                         # page asked meanwhile went unanswered
        elif ms and u["last_ms"] and ms + 2000 < u["last_ms"]:
            self._ev("link", "The board restarted (over the USB cable) - reading its settings again.", quiet=True)
            again = True
        if ms:
            u["last_ms"] = ms
        if again and self.on_connect:
            self.conn_id += 1
            self.connected_at = now
            threading.Thread(target=self.on_connect, daemon=True).start()

    def _usb_watch(self, now):
        """Called by the reader while linked over USB: keepalive, and give up on a board that can't stream."""
        u = self.usb
        if not u:
            return
        self._keepalive(now)
        if u["tel_at"]:
            return
        age = now - u["since"]
        if now - u.get("probe_at", 0.0) >= 3.0:       # a board still starting (if opening the port reset it) answers
            u["probe_at"] = now                          # once it runs: 1.9.5 streams by then, older ones only answer
            self.send(b"[rd!]")
        if self.reply_seq > u["reply0"] and not u.get("answer_at"):
            u["answer_at"] = now                         # the board answers (it may have been starting until now)
        known = self.fw_known or self.fw_version
        newfw = bool(known) and vkey(known) >= (1, 9, 5)
        if newfw and age > 20 and u.get("answer_at") and now - u["answer_at"] > 15:
            # 2.8.3: a board known to run 1.9.5+ that answers but doesn't stream: its [kU1]s get damaged on the way
            # (1.9.5 loses bytes on the USB port while the PID interrupt runs) - give it longer, then say so
            why = (f"The board (firmware {known}) answers on the cable but doesn't switch over to it: the page's "
                   "commands arrive damaged. ")
            why += ("Firmware 1.9.6 fixes that (1.9.5 loses bytes on the USB port while it controls the motors) - "
                    "install it (Settings, Firmware update, or the Arduino IDE), then run the bridge again."
                    if vkey(known) < (1, 9, 6) else
                    "Is something else using the port, or the USB cable loose? Run the bridge again to retry.")
            self._ev("link", "USB cable: " + why, quiet=False)
            self.detach_usb(why, refuse=True)
        elif not newfw and age > 6 and u.get("answer_at") and now - u["answer_at"] > 3.5:
            # it has answered for a while (and had [kU1] at least six times since), but sends no telemetry: it is
            # older than 1.9.5
            fw = self.fwnum()
            old = "1.9.4 or older" if fw == 19 else (f"{fw // 10}.{fw % 10}" if fw else "an old one")
            why = (f"The board answers on the cable, but its firmware ({old}) has no USB link - that needs firmware "
                   "1.9.5 or newer. Install it (Settings, Firmware update, or the Arduino IDE), then run the bridge "
                   "again.")
            self._ev("link", "USB cable: " + why, quiet=False)
            self.detach_usb(why, refuse=True)
        elif age > 45 and not u.get("answer_at") and self.module_reset_ok() and time.time() - self.module_reset_at >= 60:
            # 2.9: a board known to run 1.9.7 that sends nothing: its USB output has stalled - clear it
            self.module_reset_at = time.time()
            self.module_resets += 1
            self.send(b"[kE\x01]")
            why = ("Nothing came back from the board over the cable in 45 s: its USB output has stalled (a known UNO R4 "
                   "WiFi problem). The page asked the board to restart its USB chip - " + self.module_after_text())
            log("USB stall (no answer in 45 s): asked the board to restart its USB/WiFi chip ([kE1])")
            self._ev("link", "USB cable: " + why, quiet=False)
            self.detach_usb(why)
        elif age > 45 and not u.get("answer_at"):
            why = (f"The board didn't answer on {u.get('port') or 'that port'} in 45 s. Is it the Arduino's port? "
                   "(Run the bridge again: it lists the ports it can see when there are several.)")
            if u.get("probe") == "none":
                why += " The bridge got no answer either when it opened the port: nothing comes back from the board over USB."
                mod = ((self.diag or {}).get("wifi") or {})
                if mod.get("module_fw_num") and mod["module_fw_num"] < 0x000600:
                    why += (f" The board's USB chip runs firmware {mod.get('module_fw')}: updating it to 0.6.0 or newer "
                            "(Arduino's standalone updater, unor4wifi-update-windows.zip - not the IDE's Firmware "
                            "Updater, which needs these answers itself) fixed exactly this on a board that answered "
                            "nothing. See the install guide, USB cable.")
            self._ev("link", "USB cable: " + why, quiet=False)
            self.detach_usb(why, refuse=True)

    def stop(self):
        """For good (a restart into a page update, Windows): let go of the board for the next page."""
        self.stopped = True
        self._drop()

    # ---- incoming ----
    def _reader(self):
        buf = [b""]
        while not self.stopped:
            try:
                self._reader_pass(buf)
            except Exception as e:                       # never let the reader die: the page would stay disconnected
                log(f"[reader] {e!r}")
                self._drop()
                time.sleep(1.0)
        self._drop()                                     # stopped

    def _reader_pass(self, bufref):
        """One pass of the reader: connect (WiFi, or a waiting USB link), or receive and parse."""
        buf = bufref[0]
        try:
            if self.usb_pending and self.sock:           # 2.8: a bridge is waiting - end what we have, take it next
                u = self.usb
                if u and not u.get("end"):
                    u["end"] = "The bridge linked again."
                self._drop()
            if not self.sock:
                buf = b""
                if self._take_usb():                     # page 2.8: a bridge brought the USB cable
                    return
                host, port = self.cfg.get("host"), int(self.cfg.get("port"))
                if not host:
                    time.sleep(0.5)
                    return
                try:
                    s = socket.create_connection((host, port), timeout=5)
                    s.settimeout(1.0)
                    if self.usb_pending:                 # the cable arrived while this connected: take that
                        s.close()
                        return
                    with self.lock:
                        self.sock = s
                    self.link = "wifi"
                    self.conn_id += 1
                    self.ver_asks = 0
                    self.connected_at = time.time()
                    self.connected = True
                    self.current_host = host
                    self.last_rx = time.time()
                    buf = b""
                    log(f"connected to board {host}:{port}")
                    self._ev("link", f"Connected to the board at {host}:{port}.", quiet=True)
                    if self.on_connect:
                        threading.Thread(target=self.on_connect, daemon=True).start()
                except OSError:
                    self.connected = False
                    for _ in range(8):                   # 2 s, but pick up a USB link at once
                        if self.usb_pending or self.stopped:
                            break
                        time.sleep(0.25)
                    return
            usb = self.link == "usb"
            try:
                chunk = self.sock.recv(4096)
                if not chunk:
                    raise OSError("closed")
                buf += chunk
                self.last_rx = time.time()
            except socket.timeout:
                quiet = time.time() - self.last_rx
                if usb:
                    self._usb_watch(time.time())
                    u = self.usb
                    if u and u["tel_at"] and quiet > 5:
                        u["end"] = "The board stopped sending over the cable for 5 s."
                        u["quiet_end"] = True            # (2.8.2: the bridge may be cut off - it gets a minute)
                        self._module_reset(u)            # 2.9: the UNO R4 WiFi's USB stall - clear it (1.9.7)
                        self._drop()
                elif quiet > 5:
                    log("board stopped sending - reconnecting")
                    self._ev("link", "The board stopped sending data for 5 s - reconnecting.", quiet=True)
                    self._drop()
                return
            except (OSError, AttributeError):
                quick = time.time() - self.connected_at < 2.0
                u = self.usb
                if usb and u and not u.get("end"):
                    u["end"] = "The bridge closed the link (its window was closed, or the cable came out)."
                self._drop()
                if quick and not usb:                # accepted and closed at once (a board restarting, being
                    time.sleep(1.0)                  # programmed, or busy with another client): don't hammer it
                return
            buf = self._parse(buf)
            if usb:
                self._usb_watch(time.time())
            self._ask_version(time.time())
        finally:
            bufref[0] = buf

    def _drop(self):
        with self.lock:
            try:
                if self.sock:
                    self.sock.close()
            except OSError:
                pass
            was = self.sock is not None
            self.sock = None
            u, usb = self.usb, self.link == "usb"
            self.link, self.usb = "wifi", None
        if usb and u:                                    # page 2.8: the USB link ended - back to WiFi
            self.usb_want_at = time.time()               # (2.8.1: the bridge has a few seconds to link again;
            self.usb_want_grace = 70.0 if u.get("quiet_end") else 6.0   # 2.8.2: a minute when the network went quiet)
            why = u.get("end") or "The link ended."
            self.usb_last = {"computer": u.get("computer"), "port": u.get("port"), "since": u.get("since"),
                             "until": time.time(), "why": why}
            log(f"USB cable link ended: {why}")
            self._ev("link", f"The USB cable link ended: {why} The page goes back to WiFi.", quiet=True)
            u["done"].set()
        elif was:
            self.disconnected_since = time.time()
            log("disconnected from board")
            self._ev("link", "Disconnected from the board.", quiet=True)
        if usb:
            self.disconnected_since = time.time()
        self.connected = False
        self.fw_version = None

    def _parse(self, buf):
        while True:
            if len(buf) < 5:
                return buf
            if buf[:4] == b"SM3T":
                if len(buf) < 6:
                    return buf
                count = buf[5]
                need = 6 + count * SAMPLE_BYTES
                if len(buf) < need:
                    return buf
                for i in range(count):
                    self._add_sample(struct.unpack_from(SAMPLE_FMT, buf, 6 + i * SAMPLE_BYTES))
                u = self.usb
                if u and self.link == "usb":
                    self._usb_stream(u, count and struct.unpack_from("<I", buf, 6)[0])
                buf = buf[need:]
            elif buf[:4] == b"SM3I":                       # 2.9.3 / firmware 2.1.1: the motion sensor link
                if len(buf) < 6:
                    return buf
                need = 6 + buf[5]
                if len(buf) < need:
                    return buf
                d = decode_imu_info(buf[6:need], buf[4])
                if d:
                    self.imu_info = d
                    self.imu_info_seq += 1
                buf = buf[need:]
            elif buf[:4] == b"SM3X":                       # firmware 1.9: the sensor's acceleration and gyro
                if len(buf) < 6:
                    return buf
                need = 6 + buf[5]
                if len(buf) < need:
                    return buf
                if buf[5] >= 18:
                    ax, ay, az, gx, gy, gz, temp, peak, fl, n = struct.unpack_from("<3h3hhHBB", buf, 6)
                    self.imu = {"t": time.time(), "accel": [round(v / 2048.0, 4) for v in (ax, ay, az)],
                                "gyro": [round(v / 16.384, 2) for v in (gx, gy, gz)], "temp": temp / 100.0,
                                "peak_g": peak / 1000.0, "accel_ok": bool(fl & 1), "gyro_ok": bool(fl & 2), "n": n}
                    self.imu_seq += 1
                buf = buf[need:]
            elif buf[:4] == b"SM3U":                       # firmware 1.9.2: firmware update state
                if len(buf) < 6:
                    return buf
                need = 6 + buf[5]
                if len(buf) < need:
                    return buf
                if buf[5] >= 15:
                    st, code, done, total, fl, ma, mi, pa = struct.unpack_from("<BhIIBBBB", buf, 6)
                    ver = buf[21:need].split(b"\0")[0].decode("ascii", "replace") if buf[5] >= 23 else None
                    self.ota = {"t": time.time(), "state": st, "code": code, "done": done, "total": total,
                                "progress": bool(fl & 1), "remembered": bool(fl & 2),
                                "module": f"{ma}.{mi}.{pa}" if (ma or mi or pa) else None, "version": ver or None}
                    if ver:
                        self.fw_version = ver
                        self.fw_known = ver
                        if vkey(ver) >= (2, 2) and self.servo_ask_conn != self.conn_id:   # 2.9.5: servo build?
                            self.servo_ask_conn, self.servo_ask_at = self.conn_id, time.time()
                            self.send(b"[rdq]")
                    self.ota_seq += 1
                buf = buf[need:]
            elif buf[:4] == b"SM3D":                       # firmware 1.7 diagnostics frame
                if len(buf) < 6:
                    return buf
                need = 6 + buf[5]
                if len(buf) < need:
                    return buf
                d = decode_diag(buf[6:need], buf[4])
                if d:
                    self.diag = d
                    self._raw_fold(d)
                    if "seat" in d:
                        self.seat = d["seat"]
                    if "module_restart" in d:              # 2.9: firmware 1.9.8's restart report
                        self._module_report(d["module_restart"])
                    self.diag_seq += 1
                buf = buf[need:]
            elif buf[0:1] == b"[" and buf[4:5] == b"]":
                self._add_reply(chr(buf[1]), buf[2], buf[3])
                buf = buf[5:]
            else:
                buf = buf[1:]          # resync

    def _add_sample(self, u):
        motors = []
        status, power, roll, pitch, yaw, isr = u[13:19]
        for m in range(3):
            t, g, f, p = u[1 + m * 4: 5 + m * 4]
            d, o = self.drive(m, g, f, p, status & (1 << m))
            motors.append({"t": t, "g": g / 16.0, "f": f / 16.0, "p": p / 16.0, "d": d, "o": o})
        # seat angles: firmware 1.8 sends -32768 when the sensor is silent; older firmware sends 0 without one
        if roll == -32768 or (roll == 0 and pitch == 0 and yaw == 0 and (self.fw_cache or [0, 0])[1] < 18):
            roll = pitch = yaw = None
        with self.slock:
            self.seq += 1
            self.samples.append({
                "seq": self.seq, "ms": u[0], "m": motors,
                "dis": [bool(status & 1), bool(status & 2), bool(status & 4)],
                "div": status >> 4, "low": power == 9,
                "roll": None if roll is None else roll / 100.0, "pitch": None if pitch is None else pitch / 100.0,
                "yaw": None if yaw is None else yaw / 100.0, "isr": isr,
            })

    def _add_reply(self, code, a, b):
        self.reply_seq += 1
        if code in SERVO_CODES:                      # 2.9.5: only a servo build answers these
            if code == "q" and (a & 1):
                self.servo_conn = self.conn_id
            name, kind = SERVO_CODES[code]
            self.params[name] = (a * 256 + b) if kind == "w" else [a, b]
            return
        if code not in PARAM_CODES:
            return
        name, kind = PARAM_CODES[code]
        self.params[name] = (a * 256 + b) if kind == "w" else [a, b]
        self.pm[name] = self.params[name]
        if name == "FW":
            self.fw_cache = [a, b]

    def latest(self):
        with self.slock:
            return self.samples[-1] if self.samples else None

    def since(self, seq, limit=None):
        with self.slock:
            snap = list(self.samples)
        out = [s for s in snap if s["seq"] > seq]
        return out[-limit:] if limit else out


# --------------------------------------------------------------------------------------------------------------
# Finding the board on the network
# --------------------------------------------------------------------------------------------------------------

def subnet_of(host, override=""):
    if override:
        return override.strip().rstrip(".")
    try:
        ip = socket.gethostbyname(host) if host else ""
    except OSError:
        ip = ""
    parts = ip.split(".")
    if len(parts) == 4 and all(p.isdigit() for p in parts):
        return ".".join(parts[:3])
    return "192.168.1"


def scan_for_boards(prefix, port, skip=()):
    """Try every address in prefix.1-254 for an SMC3 telemetry stream. Returns the addresses that answer."""
    def probe(h):
        if h in skip:
            return None
        try:
            s = socket.create_connection((h, port), timeout=0.4)
        except OSError:
            return None
        try:
            s.settimeout(0.5)
            data = b""
            end = time.time() + 4.0
            while time.time() < end and b"SM3T" not in data:
                try:
                    chunk = s.recv(2048)
                    if not chunk:
                        break
                    data += chunk
                except socket.timeout:
                    pass
            return h if b"SM3T" in data else None
        finally:
            s.close()

    hosts = [f"{prefix}.{i}" for i in range(1, 255)]
    with ThreadPoolExecutor(max_workers=64) as ex:
        return [h for h in ex.map(probe, hosts) if h]


class AutoFinder:
    """If the board stays unreachable for a minute, look for it on the subnet (then every 10 minutes)."""
    def __init__(self, board, cfg):
        self.board, self.cfg = board, cfg
        self.last_scan = 0.0
        self.scanning = False
        threading.Thread(target=self._loop, daemon=True).start()

    def scan_now(self, subnet=""):
        if self.scanning:
            return None
        self.scanning = True
        try:
            prefix = subnet_of(self.cfg.get("host"), subnet or self.cfg.get("scan_subnet"))
            skip = (self.board.current_host,) if self.board.connected else ()
            found = scan_for_boards(prefix, int(self.cfg.get("port")), skip)
            self.last_scan = time.time()
            return prefix, found
        finally:
            self.scanning = False

    def _loop(self):
        while True:
            time.sleep(5)
            b = self.board
            if (not self.cfg.get("auto_find") or b.connected or self.scanning
                    or time.time() - b.disconnected_since < 60 or time.time() - self.last_scan < 600):
                continue
            r = self.scan_now()
            if not r:
                continue
            prefix, found = r
            if found and found[0] != self.cfg.get("host"):
                log(f"auto-find: board found at {found[0]} (was {self.cfg.get('host')}) - switching")
                self.cfg.update(host=found[0])
                b.reconnect()
            else:
                log(f"auto-find: no board answering on {prefix}.x")


# --------------------------------------------------------------------------------------------------------------
# Test-signal generator (sends [Axx]/[Bxx]/[Cxx] at 50 Hz). Stop SimHub motion while using it.
# --------------------------------------------------------------------------------------------------------------

COMBOS = {                     # 2.9: test signals on several motors at once (the Test Signal card, Presets)
    "twist": "the two front lifts opposite each other (one up while the other goes down) - the most twist",
    "heave": "the lifts together, up and down",
    "corner": "the front lifts opposite each other and the rear slide with them, as in a corner",
    "wave": "every motor in turn, a third of a cycle apart",
}


def up_sign(cfg, m, fw_flags=0):
    """+1 when a higher position command lifts lift m, -1 when it lowers it (as the tuner reads the rig: the full
    check's answer, else away from where the corner sinks, else as SimHub expects; REVERSE_MOTOR1 mirrors motor 1)."""
    rev = m == 0 and bool(fw_flags & 1)          # (lift_dir / lift_sink are in pot counts, as the tuner sees them)
    seen = (cfg.get("lift_dir") or {}).get(str(m + 1))
    sink = (cfg.get("lift_sink") or {}).get(str(m + 1))
    if seen in (1, -1, "1", "-1"):
        d = 1 if int(seen) > 0 else -1
    elif sink in (1, -1, "1", "-1"):
        d = -1 if int(sink) > 0 else 1
    else:
        d = -1 if rev else 1
    return -d if rev else d                      # the generator sends position commands, mirrored for motor 1


def combo_plan(cfg, combo, fw_flags=0):
    """[(motor, sign, phase)] for a several-motor test signal, or None when this rig hasn't the motors for it."""
    n = int(cfg.get("motors") or 3)
    lifts, tl = lift_motors(cfg), tl_motor(cfg)
    if combo == "twist" and len(lifts) >= 2:
        a, b = lifts[0], lifts[1]
        return [(a, up_sign(cfg, a, fw_flags), 0.0), (b, -up_sign(cfg, b, fw_flags), 0.0)]
    if combo == "heave" and len(lifts) >= 2:
        return [(m, up_sign(cfg, m, fw_flags), 0.0) for m in lifts]
    if combo == "corner" and len(lifts) >= 2 and tl is not None:
        a, b = lifts[0], lifts[1]
        return [(a, up_sign(cfg, a, fw_flags), 0.0), (b, -up_sign(cfg, b, fw_flags), 0.0), (tl, 1, 0.0)]
    if combo == "wave" and n >= 2:
        ms = list(range(n))
        return [(m, up_sign(cfg, m, fw_flags) if m in lifts else 1, i / len(ms)) for i, m in enumerate(ms)]
    return None


class Generator:
    """Test signals (sine, square, triangle, or a value held) on one motor or several (combos). 2.9.1: they start
    and stop gently - a wave fades in from where each motor is over about a second (it used to start wherever its
    cycle happened to be, a jump of up to its full amplitude: a hard kick that made the seat jiggle) and, stopped,
    eases back to its centre; changing the amplitude or the offset while it runs slides to the new one, and the
    period changes without a jump (the cycle is counted, not taken from the clock). "manual" (the Step preset, the
    manual value) still goes straight to its value - that is the point of a step."""
    FADE_OUT = 0.8

    def __init__(self, board):
        self.board = board
        self.mode = "off"
        self.motor = 0
        self.amp = 200
        self.period = 2.0
        self.value = 512
        self.centre = 512
        self.combo = ""                # 2.9: "" = one motor, else a COMBOS key
        self.plan = []                 # [(motor, sign, phase, centre)] for a combo
        self.lock = threading.Lock()
        self.sent = {}                 # motor -> the last value sent
        self.fade = None               # {"t0", "dur", "from": {m: v}, "out": bool}
        self.phase = 0.0               # cycles since the wave started
        self.amp_s = None              # amplitude and offset as sent (they slide to self.amp / self.centre)
        self.centre_s = None
        self.show = None               # 2.9.3: a motion preset from the 3D view (see show_part.py)
        self.show_msg = ""             # how the last one ended
        self.show_msg_id = 0
        self.on_show_end = None        # (kind "stop" | "level", positions, msg) -> the page holds the seat on (main)
        threading.Thread(target=self._run, daemon=True).start()

    def _start_pos(self, m):
        if m in self.sent:
            return self.sent[m]
        s = self.board.latest()
        return float(s["m"][m]["t"]) if s else 512.0

    def _targets(self, mode=None, combo=None, plan=None, motor=None):
        mode = self.mode if mode is None else mode
        if mode == "off":
            return []
        if (self.combo if combo is None else combo) and (self.plan if plan is None else plan):
            return [m for m, *_ in (self.plan if plan is None else plan)]
        return [self.motor if motor is None else motor]

    def set(self, **kw):
        with self.lock:
            old = (self.mode, self.combo, self.motor, tuple(m for m, *_ in self.plan))
            before = set(self._targets())
            cen_old = {m: c for m, sg, ph, c in self.plan} if (self.combo and self.plan) else {}
            cen_one = float(self.centre_s if self.centre_s is not None else self.centre)
            for k, v in kw.items():
                if hasattr(self, k) and k not in ("lock", "sent", "fade"):
                    setattr(self, k, v)
            new = (self.mode, self.combo, self.motor, tuple(m for m, *_ in self.plan))
            if new == old:
                return                                    # amplitude / period / offset: they slide (in _run)
            now = time.time()
            if self.mode == "off":
                if old[0] in ("off", "manual") or not self.sent:
                    self.fade, self.sent = None, {}        # a held value just stays, as before
                else:
                    self.fade = {"t0": now, "dur": self.FADE_OUT, "from": dict(self.sent), "out": True,
                                 "to": {m: cen_old.get(m, cen_one) for m in self.sent}}
                return
            if self.mode == "manual":
                self.fade = None
                return
            # a new wave (or another shape, motor or combo): fade in from where each motor is now; a motor the old
            # wave moved that the new one doesn't goes back to its centre at the same time
            frm = {m: self._start_pos(m) for m in set(self._targets()) | before}
            self.phase = 0.0
            self.amp_s, self.centre_s = float(self.amp), float(self.centre)
            per = max(0.05, float(self.period))
            self.fade = {"t0": now, "dur": max(0.8, min(2.0, 0.5 * per)), "from": frm, "out": False,
                         "leaving": {m: cen_old.get(m, cen_one) for m in before - set(self._targets())}}

    def stop_now(self):
        """Off at once, no easing back - for auto-tune, the full check, Seat setup and a restart, which move the
        motors themselves straight after."""
        with self.lock:
            if self.mode == "show" and self.show:
                self._show_note(f"{self.show['title']} stopped: something else moves the motors now.")
            self.mode, self.fade, self.sent, self.combo, self.plan = "off", None, {}, "", []
            self.show = None

    # ---- 2.9.3: motion presets (the 3D view) ----
    def _show_note(self, msg):
        self.show_msg, self.show_msg_id = msg, self.show_msg_id + 1

    def start_show(self, name, plan, intensity, speed):
        """Run preset name on the motors in plan (show_plan): from where they are, into the motion over SHOW_FADE."""
        s = self.board.latest()
        now = time.time()
        frm = {}
        for m, info in plan.items():
            t = float(s["m"][m]["t"]) if s else info["c"]
            frm[m] = (1023.0 - t) if info["rev"] else t          # telemetry targets are the board's (mirrored) ones
        dur = SHOWS[name][0]
        with self.lock:
            self.mode, self.combo, self.fade, self.sent = "show", "show", None, {}
            self.plan = [(m, 0, 0.0, info["c"]) for m, info in plan.items()]
            self.show = {"name": name, "title": name.capitalize(), "plan": plan, "t": 0.0, "t0": now, "dur": dur,
                         "intensity": float(intensity), "k": float(intensity), "speed": float(speed), "from": frm,
                         "sent": dict(frm), "hold": 0.0, "label": "", "conn": self.board.conn_id}

    def set_show(self, intensity=None, speed=None):
        with self.lock:
            if self.mode == "show" and self.show:
                if intensity is not None:
                    self.show["intensity"] = float(intensity)
                if speed is not None:
                    self.show["speed"] = float(speed)

    def stop_show(self, kind, msg=None):
        """Stop the preset: "stop" holds the seat where it is, "level" glides it back to level (the page keeps it)."""
        with self.lock:
            if self.mode != "show" or not self.show:
                return False
            pend = self._show_finish(kind, msg or (f"{self.show['title']} stopped" +
                                                   (" - back to level." if kind == "level" else " - the seat holds "
                                                    "where it is.")))
        self._show_handover(pend)
        return True

    def _show_finish(self, kind, msg):
        pos = dict(self.show["sent"])
        self._show_note(msg)
        self.mode, self.fade, self.sent, self.combo, self.plan = "off", None, {}, "", []
        self.show = None
        return kind, pos, msg

    def _show_handover(self, pend):
        if pend and pend[0] and self.on_show_end:
            try:
                self.on_show_end(*pend)
            except Exception as e:                           # never let the generator die
                log(f"[show] hand-over: {e!r}")

    def show_status(self):
        S = self.show
        if self.mode != "show" or not S:
            return {"active": False, "msg": self.show_msg, "msg_id": self.show_msg_id}
        return {"active": True, "name": S["name"], "title": S["title"], "label": S["label"], "t": round(S["t"], 1),
                "dur": S["dur"], "intensity": S["intensity"], "speed": S["speed"], "msg": self.show_msg,
                "msg_id": self.show_msg_id}

    def _show_tick(self, now, dt):
        """One pass (50 a second): where every motor goes now. Returns a hand-over when it ends, else None."""
        S, b = self.show, self.board
        if not b.connected or b.conn_id != S["conn"]:
            self._show_finish(None, f"{S['title']} stopped: the connection to the board dropped (SimHub has the seat "
                                    f"again).")
            return None
        st = b.latest()
        off = [m + 1 for m in S["plan"] if st and st["dis"][m]]
        if off:
            return self._show_finish("stop", f"{S['title']} stopped: motor {' and '.join(map(str, off))} switched off. "
                                             f"The page holds the others where they are.")
        if S["dur"] is None:
            S["t"] += dt * max(0.25, min(3.0, S["speed"]))
        else:
            S["t"] += dt
            if S["t"] >= S["dur"]:
                return self._show_finish("level", f"{S['title']} done - the seat glides back to level; the page holds "
                                                  f"it there until Resume SimHub.")
        S["k"] += (max(0.0, min(1.0, S["intensity"])) - S["k"]) * min(1.0, dt / 0.5)    # Intensity slides
        u, S["label"] = show_pose(S["name"], S["t"], {m: i["role"] for m, i in S["plan"].items()})
        e = _ss((now - S["t0"]) / SHOW_FADE)
        step = SHOW_SLEW * dt
        for m, info in S["plan"].items():
            v = info["c"] + info["sign"] * info["room"] * S["k"] * u.get(m, 0.0)
            v = S["from"][m] + (v - S["from"][m]) * e
            last = S["sent"][m]
            v = max(last - step, min(last + step, v))
            v = max(info["lo"], min(info["hi"], v))
            S["sent"][m] = v
            cmd = 1023.0 - v if info["rev"] else v
            self.sent[m] = cmd
            b.cmd_word("ABC"[m], int(round(cmd)))
        if now - S["hold"] >= 1.0:                           # SimHub's positions wait while the page has the seat
            b.seat_cmd(ord("H"), SHOW_HOLD)
            S["hold"] = now
        return None

    def drives(self, m):
        """True while the test signal sends positions to motor m (also while it eases back after Stop)."""
        with self.lock:
            if self.fade and m in self.fade["from"]:
                return True
            return m in self._targets()

    def _wave(self, ph):
        if self.mode == "sine":
            return math.sin(2 * math.pi * ph)
        if self.mode == "step":
            return 1.0 if int(ph * 2) % 2 else -1.0
        if self.mode == "triangle":
            p = ph % 1.0
            return 4 * p - 1 if p < 0.5 else 3 - 4 * p
        return 0.0

    def _send(self, m, v):
        v = max(0.0, min(1023.0, v))
        self.sent[m] = v
        self.board.cmd_word("ABC"[m], int(round(v)))

    def _run(self):
        last = time.time()
        while True:
            time.sleep(0.02)
            now = time.time()
            dt, last = min(0.1, now - last), now
            if self.mode == "show":                          # 2.9.3: a motion preset (the 3D view)
                pend = None
                with self.lock:
                    if self.mode == "show" and self.show:
                        try:
                            pend = self._show_tick(now, dt)
                        except Exception as e:               # a bug: stop it and hold the seat where it is
                            log(f"[show] {e!r}")
                            pend = self._show_finish("stop", f"Motion preset stopped: internal error {e!r}")
                self._show_handover(pend)
                continue
            with self.lock:
                fd = self.fade
                e = 1.0
                if fd:
                    x = min(1.0, (now - fd["t0"]) / fd["dur"])
                    e = 0.5 - 0.5 * math.cos(math.pi * x)        # eases in and out
                if self.mode == "off":
                    if fd and fd["out"]:
                        for m, v0 in fd["from"].items():
                            c = fd["to"].get(m, v0)
                            self._send(m, v0 + (c - v0) * e)
                        if e >= 1.0:
                            self.fade, self.sent = None, {}
                    continue
                if self.mode == "manual":
                    self.fade = None
                    self._send(self.motor, float(self.value))
                    continue
                per = max(0.05, float(self.period))
                self.phase += dt / per
                # amplitude and offset changes slide over ~0.4 s
                k = min(1.0, dt / 0.4)
                self.amp_s = float(self.amp) if self.amp_s is None else self.amp_s + (float(self.amp) - self.amp_s) * k
                self.centre_s = (float(self.centre) if self.centre_s is None else
                                 self.centre_s + (float(self.centre) - self.centre_s) * k)
                plan = self.plan if (self.combo and self.plan) else [(self.motor, 1, 0.0, None)]
                for m, sign, phase, centre in plan:
                    c = (centre + (self.centre_s - self.centre)) if centre is not None else self.centre_s
                    v = c + sign * self.amp_s * self._wave(self.phase + phase)
                    if fd and not fd["out"] and m in fd["from"]:
                        v = fd["from"][m] + (v - fd["from"][m]) * e
                    self._send(m, v)
                if fd and not fd["out"]:
                    for m, c in fd.get("leaving", {}).items():
                        v0 = fd["from"].get(m, c)
                        self._send(m, v0 + (c - v0) * e)
                    if e >= 1.0:
                        for m in fd.get("leaving", {}):
                            self.sent.pop(m, None)
                        self.fade = None


