# Auto-tune
# --------------------------------------------------------------------------------------------------------------

class TuneAbort(Exception):
    def __init__(self, msg, kind="benign"):        # benign | unsafe | refuse
        super().__init__(msg)
        self.kind = kind


# style -> (overshoot allowed %, cap as share of the highest stable Kp, how close to the best is "enough",
#           how far behind a test move the motor may follow, ms - page 2.5)
STYLES = {"gentle": (5.0, 0.85, 1.30, 120.0), "normal": (10.0, 0.90, 1.15, 80.0), "firm": (15.0, 0.95, 1.05, 50.0)}
SSE_FLOOR = 12.0             # never pick a Kp that leaves more than this many counts of error on big moves
PID_NOISE_MAX = 6.0          # PWM std of the PID output while holding - above this it buzzes
KP_START, KP_STEP, KP_MAX = 40, 1.3, 2000
OS_STOP = 30.0
KI_STEPS = [5, 10, 20, 40, 70]
KI_SMALL = 2                 # 2.9: tried when the first step already overshoots
KD_STEPS = [5, 10, 20, 40]
SPEED_KP = (120, 200)        # Kp range for the one quick move each way that measures the top speed (page 2.5)
QUICK_V, QUICK_EASE = 1800.0, 0.2   # 2.9.1: that quick move's target runs at 1800 counts/s, easing in and out over
                             # 0.2 s - faster than these motors can go, so they still give everything, but the drive
                             # builds up over a moment instead of a jump of the target slamming full power on
RAMP_SHARE = 0.6             # test moves run at this share of the slower direction's top speed, so the motor can follow
RIDER_REF_KG = 80.0          # a rider this heavy (176 lb) gets the full allowance when the seat is tuned empty
COUNTDOWN_S = 15             # "I'm in the seat": time to get in before anything moves
SETTLE_OK_MS = 500           # gauges: settling within this is good, within twice this is fair
SMALL_STEP = 30              # small test steps (kerb-sized), counts each way from the start position (page 2.6)
RAMP_MIN_S = 0.3             # a test move takes at least this long, so a short travel still gets a gradual move
PHASES = [("countdown", "Get in"), ("prep", "Prepare"), ("noise", "Pot noise"), ("pwmmin", "Min drive"),
          ("speed", "Top speed"), ("kp", "Kp sweep"), ("small", "Small moves"), ("ki", "Ki"), ("kd", "Kd"),
          ("final", "Final check")]
JOINT_PHASES = [("prep", "Prepare"), ("noise", "Pot noise"), ("solo", "Each alone"), ("together", "Together"),
                ("opposite", "Twisted"), ("end", "Back")]
CHECK_PHASES = [("countdown", "Get in"), ("prep", "Prepare"), ("noise", "Pot noise"), ("speed", "Top speed"),
                ("big", "Test moves"), ("small", "Small moves")]


def _mean(xs):
    return sum(xs) / len(xs) if xs else 0.0


def _std(xs):
    return statistics.pstdev(xs) if len(xs) > 1 else 0.0


def _rstd(xs):
    """Spread that a few glitchy readings can't inflate (2.4.1): 1.4826 x the median absolute deviation."""
    if len(xs) < 5:
        return _std(xs)
    med = statistics.median(xs)
    return 1.4826 * statistics.median(abs(x - med) for x in xs)


def _hold_spread(ts, xs):
    """2.9: how restless a hold is - over its last 0.9 s (not just 0.3 s), with a slow creep taken out (the line
    through the medians of the first and last thirds) and as a median spread (1.4826 x MAD). A motor hunting because
    Kp is too high does it the whole time and counts in full; a crackling pot's burst (50-300 ms of readings a few
    counts off, too small for the firmware's glitch filter) covers a third of the window at most and hardly counts.
    On 0.3 s one burst filled the window: the sweep stopped on it and called the motor "too lively"."""
    if len(xs) < 15:
        return _rstd(xs)
    k = len(xs) // 3
    t1, t3 = _mean(ts[:k]), _mean(ts[-k:])
    m1, m3 = statistics.median(xs[:k]), statistics.median(xs[-k:])
    slope = (m3 - m1) / (t3 - t1) if t3 > t1 else 0.0
    tm = _mean(ts)
    return _rstd([x - slope * (t - tm) for x, t in zip(xs, ts)])


def _med3(xs):
    """3-reading running median: a single noisy pot reading can't cross a threshold on its own."""
    if len(xs) < 3:
        return list(xs)
    return [xs[0]] + [sorted(xs[i - 1:i + 2])[1] for i in range(1, len(xs) - 1)] + [xs[-1]]


def _med5(xs):
    """5-reading running median (2.4.1): a burst of glitchy readings (a few in a row) can't become a step's peak - a
    motor's real overshoot lasts far longer than 30 ms."""
    if len(xs) < 5:
        return list(xs)
    return xs[:2] + [sorted(xs[i - 2:i + 3])[2] for i in range(2, len(xs) - 2)] + xs[-2:]


def _med7(xs):
    """7-reading running median (page 2.5): a glitchy pot's bursts - up to three bad readings in a row - can't make a
    peak, a late excursion or a swing; a motor's real overshoot lasts longer than 70 ms. Only where the full window
    fits: the first and last three readings are left out (a burst there would pass through)."""
    n = len(xs)
    if n < 10:
        return list(xs)
    return [sorted(xs[i - 3:i + 4])[3] for i in range(3, n - 3)]


def _hampel(xs, k=5, floor=10.0):
    """Pot readings with glitches replaced (page 2.5): a reading more than max(floor, 4.5 sigma) away from the median
    of the 2k+1 readings around it becomes that median. A glitchy pot's bad readings come in clusters - on the
    owner's rig about 80 a second - so a 3- or 7-reading median isn't enough; real movement passes untouched (on a
    steady move the median of the window is the reading in its middle)."""
    n = len(xs)
    out = list(xs)
    for i in range(n):
        w = xs[max(0, i - k):min(n, i + k + 1)]
        med = statistics.median(w)
        mad = statistics.median(abs(x - med) for x in w)
        if abs(xs[i] - med) > max(floor, 4.5 * 1.4826 * mad):
            out[i] = med
    return out


def _top_speed(post, fs, sgn):
    """Fastest the pot moved during a move (counts/s): its speed over 100 ms windows, taken over the part of the window
    where it really moved (above 30% of the 95th percentile), and the 75th percentile of that - so neither the rest
    before and after nor one glitchy reading decides it."""
    vs = []
    for i in range(5, len(post) - 5):
        dt = post[i + 5]["ms"] - post[i - 5]["ms"]
        if dt > 0:
            vs.append((fs[i + 5] - fs[i - 5]) * sgn / dt * 1000.0)
    if len(vs) < 5:
        return None
    vs.sort()
    ref = vs[int(0.95 * (len(vs) - 1))]
    if ref <= 0:
        return 0.0
    moving = [x for x in vs if x > 0.3 * ref]
    return moving[int(0.75 * (len(moving) - 1))]


def _settle_metrics(ys, fs, post, f0, t_new, size, sgn, noise, m, t_from):
    """What happens once the target stops: overshoot, settling, leftover error, ringing (shared by steps and ramps).
    Judged on a 7-reading running median (page 2.5): a glitchy pot's bursts of two or three bad readings in a row got
    past the 3-reading median and counted as ringing or slow settling; a motor's real swings last longer than 70 ms."""
    span = ys[-1][1]
    tail = [s for y, t, s in ys if t >= span - 300]
    fb_tail = [s["m"][m]["f"] for s in tail]
    final = statistics.median([f for f, s in zip(fs, post) if s["ms"] - t_from >= span - 300])
    sse = (t_new - final) * sgn                                    # leftover error = Ki's job
    # Dynamics are judged against where the seat actually comes to rest, so a few counts of leftover
    # error (sag) don't masquerade as slow settling or overshoot.
    yf = (final - f0) * sgn / size
    tol = max(3.0, 0.03 * size, 3.0 * noise)
    y5 = _med7([y for y, _, _ in ys])
    ts = [t for _, t, _ in ys]
    if len(y5) < len(ts):                    # the 7-reading median leaves out the first and last three readings
        ts = ts[3:-3]
    peak = max(y5)
    os_pct = max(0.0, (peak - yf) * 100.0)
    last_out = None
    for y, t in zip(y5, ts):
        if abs(y - yf) * size > tol:
            last_out = t
    settle = last_out or 0
    settled = (span - settle) >= 200
    t_near = next((t for y, t in zip(y5, ts) if y >= 0.9 * yf), None) if yf > 0.2 else None
    crossings, state = 0, 0
    for y, t in zip(y5, ts):
        if t_near is None or t < t_near:
            continue
        e = (yf - y) * size
        st = 1 if e > tol else (-1 if e < -tol else 0)
        if st == 0:
            continue
        if state and st != state:
            crossings += 1
        state = st
    hold = [(t, s) for y, t, s in ys if t >= max(span - 900, 0.35 * span)]      # 2.9: see _hold_spread
    hts = [t for t, s in hold]
    return {"os": os_pct, "settle": settle, "settled": settled, "sse": abs(sse), "osc": crossings,
            "fb_std": _hold_spread(hts, [s["m"][m]["f"] for t, s in hold]),
            "pid_std": _hold_spread(hts, [s["m"][m]["p"] for t, s in hold])}


def _wrong_start(early, m, f0, sgn, noise):
    """Started the wrong way: 3 readings in a row clearly behind where it started - on the 7-reading median (page
    2.5), so a glitchy pot's burst of three bad readings can't fake it; a motor really going the wrong way keeps
    going for far longer."""
    lim_w, run, wrong = max(15.0, 4.0 * noise), 0, False
    fs = _med7(_hampel([s["m"][m]["f"] for s in early]))
    for f in fs:
        run = run + 1 if (f - f0) * sgn < -lim_w else 0
        wrong = wrong or run >= 3
    if wrong:
        log(f"[tune] wrong-way start: from {f0:.1f} ({'up' if sgn > 0 else 'down'}), readings "
            f"{[round(s['m'][m]['f']) for s in early[:40]]}")
    return wrong


def _small_move(post, m, t_new, size):
    fb_tail = [s["m"][m]["f"] for s in post[-30:]]
    return {"size": size, "rise": 0.0, "reached": True, "os": 0.0, "settle": 0.0, "settled": True,
            "sse": abs(t_new - _mean(fb_tail)), "osc": 0, "fb_std": _rstd(fb_tail),
            "pid_std": _rstd([s["m"][m]["p"] for s in post[-30:]]), "sat": 0.0, "wrong": False,
            "lag": None, "lag_ms": None, "lag_end": None, "drive": None, "behind": False, "vtop": None}


def _before(samples, idx, m, t_old):
    """Where the motor was before a move: the median of up to 15 readings at rest at the old target."""
    pre = [s["m"][m]["f"] for s in samples[max(0, idx - 15):idx] if s["m"][m]["t"] == t_old]
    return statistics.median(pre or [s["m"][m]["f"] for s in samples[max(0, idx - 15):idx]] or [samples[idx]["m"][m]["f"]])


def analyze_step(samples, m, t_old, pwmmin, pwmmax, window_ms, noise=0.0, after_seq=None):
    """Step-response metrics for motor m from telemetry samples that contain a target change away from t_old.
    noise: the pot's noise at rest (1 sigma, counts) - tolerances grow with it, so a noisy pot doesn't read as
    ringing, slow settling or a wrong-way start (page 2.4)."""
    idx = next((i for i, s in enumerate(samples) if s["m"][m]["t"] != t_old
                and (after_seq is None or s["seq"] > after_seq)), None)
    if idx is None:
        return None
    t_new = samples[idx]["m"][m]["t"]
    f0 = _before(samples, idx, m, t_old)
    t0 = samples[idx]["ms"]
    post = [s for s in samples[idx:] if 0 <= s["ms"] - t0 <= window_ms and s["m"][m]["t"] == t_new]
    size = abs(t_new - f0)
    if len(post) < 10:
        return None
    if size < 8:     # the seat was already (nearly) there - nothing to measure except where it rests
        return dict(_small_move(post, m, t_new, size), kind="step")
    sgn = 1 if t_new >= f0 else -1
    fs = _med3(_hampel([s["m"][m]["f"] for s in post]))
    ys = [((f - f0) * sgn / size, s["ms"] - t0, s) for f, s in zip(fs, post)]
    t10 = next((t for y, t, _ in ys if y >= 0.1), None)
    # 90% of the way to the TARGET - on a small step, within the tolerance of it (a 30-count step can't be asked to
    # get within 3 counts when the dead zone is 3)
    thr = min(0.9, 1.0 - (max(3.0, 0.03 * size, 3.0 * noise) + 1.0) / size)
    t90 = next((t for y, t, _ in ys if y >= thr), None)
    out = _settle_metrics(ys, fs, post, f0, t_new, size, sgn, noise, m, t0)
    rising = [s for y, t, s in ys if t90 is None or t <= t90]
    sat = _mean([1.0 if abs(s["m"][m]["p"]) + pwmmin >= pwmmax else 0.0 for s in rising])
    out.update({
        "kind": "step", "size": size, "rise": (t90 - t10) if (t10 is not None and t90 is not None) else None,
        "reached": t90 is not None, "sat": sat, "wrong": _wrong_start([s for y, t, s in ys if t <= 500], m, f0, sgn, noise),
        "lag": None, "lag_ms": None, "lag_end": None, "drive": None, "behind": False,
        "vtop": _top_speed(post, fs, sgn),
    })
    return out


def analyze_move(samples, m, t_old, pwmmin, pwmmax, window_ms, noise=0.0, after_seq=None):
    """Metrics for one test move of motor m away from t_old (page 2.5). If the target jumped, it's a step (see
    analyze_step). If it moved there along a ramp: how far the motor trails the board's goal while it follows
    (counts, and ms at the ramp's speed), whether it falls further and further behind, how much of PWMmax that
    takes - then, once the target stops, overshoot, settling, leftover error and ringing as for a step."""
    idx = next((i for i, s in enumerate(samples) if s["m"][m]["t"] != t_old
                and (after_seq is None or s["seq"] > after_seq)), None)
    if idx is None:
        return None
    t_new = samples[-1]["m"][m]["t"]
    end = next((i for i in range(idx, len(samples)) if samples[i]["m"][m]["t"] == t_new), None)
    if end is None:
        return None
    if samples[end]["ms"] - samples[idx]["ms"] < 60:               # the target jumped: a step
        return analyze_step(samples, m, t_old, pwmmin, pwmmax, window_ms, noise, after_seq)
    f0 = _before(samples, idx, m, t_old)
    t0, te = samples[idx]["ms"], samples[end]["ms"]
    dur = te - t0
    post = [s for s in samples[end:] if 0 <= s["ms"] - te <= window_ms and s["m"][m]["t"] == t_new]
    size = abs(t_new - f0)
    if len(post) < 10:
        return None
    if size < 8:
        return dict(_small_move(post, m, t_new, size), kind="ramp")
    sgn = 1 if t_new >= f0 else -1
    ramp = samples[idx:end]
    whole = [s for s in samples[idx:] if s["ms"] - te <= window_ms]
    fr = _med3(_hampel([s["m"][m]["f"] for s in ramp]))
    # the motor didn't get to the last target before this move began (a far too soft Kp): the goal passes it on the
    # way, so "how far behind" means nothing for this move
    started_off = abs(f0 - t_old) > max(10.0, 0.25 * size)
    cruise = [(s, f) for s, f in zip(ramp, fr) if s["ms"] - t0 >= 0.35 * dur]
    lags = [(s["m"][m]["g"] - f) * sgn for s, f in cruise]        # how far the motor trails the board's goal
    lag = statistics.median(lags) if lags else None
    lag_end = statistics.median(lags[-5:]) if len(lags) >= 5 else lag
    v = None
    if len(cruise) >= 5:
        dt = cruise[-1][0]["ms"] - cruise[0][0]["ms"]
        if dt > 0:
            v = (cruise[-1][0]["m"][m]["g"] - cruise[0][0]["m"][m]["g"]) * sgn / dt * 1000.0
    if not v or v < 5:
        v = abs(t_new - t_old) / max(1.0, dur) * 1000.0
    drives = [min(pwmmax, abs(s["m"][m]["p"]) + pwmmin) for s, _ in cruise]
    # falls behind: out of drive, the motor can't keep up with the goal, so the gap keeps growing. Judged where the
    # goal still moves at (nearly) full speed - the motor's speed against the goal's over that same stretch, on the
    # medians of a few readings at each end so pot noise can't fake it - and only with the drive at or near PWMmax
    # there. (2.5 compared the motor's speed in the last quarter of the ramp with the goal's average speed: with 2.6's
    # shorter moves that last quarter is all easing-out, where the goal itself slows down, so it flagged most tests.)
    behind = False
    gs = [s["m"][m]["g"] for s in ramp]
    mss = [s["ms"] for s in ramp]
    fast = [i for i in range(2, len(ramp) - 2) if mss[i + 2] > mss[i - 2]
            and (gs[i + 2] - gs[i - 2]) * sgn / (mss[i + 2] - mss[i - 2]) * 1000.0 >= 0.8 * v]
    if len(fast) >= 6 and lag_end is not None and v:
        i0, i1 = fast[0], fast[-1]
        dt = (mss[i1] - mss[i0]) / 1000.0
        if dt >= 0.06:
            vm = (statistics.median(fr[max(i0, i1 - 2):i1 + 1]) - statistics.median(fr[i0:i0 + 3])) * sgn / dt
            vg = (gs[i1] - gs[i0]) * sgn / dt
            sat_fast = _mean([1.0 if abs(ramp[i]["m"][m]["p"]) + pwmmin >= 0.95 * pwmmax else 0.0 for i in fast])
            behind = (vg > 0 and vm < 0.85 * vg and sat_fast >= 0.5
                      and lag_end > max(6.0, 3.0 * noise, 0.05 * size))
    if started_off:
        lag = lag_end = None
        behind = False
    fs = _med3(_hampel([s["m"][m]["f"] for s in post]))
    ys = [((f - f0) * sgn / size, s["ms"] - te, s) for f, s in zip(fs, post)]
    out = _settle_metrics(ys, fs, post, f0, t_new, size, sgn, noise, m, te)
    early = [s for s in samples[idx:] if s["ms"] - t0 <= 500]
    out.update({
        "kind": "ramp", "size": size, "rise": None,
        "reached": any(y >= 0.9 for y, _, _ in ys), "wrong": _wrong_start(early, m, f0, sgn, noise),
        "sat": _mean([1.0 if abs(s["m"][m]["p"]) + pwmmin >= pwmmax else 0.0 for s, _ in cruise]),
        "lag": lag, "lag_end": lag_end, "lag_ms": (max(0.0, lag) / v * 1000.0) if (lag is not None and v > 0) else None,
        "v": v, "drive": statistics.median(drives) if drives else None, "behind": behind,
        # 2.9.1: the fastest the motor went over the whole move (the eased quick move for the top speed is a ramp)
        "vtop": _top_speed(whole, _med3(_hampel([s["m"][m]["f"] for s in whole])), sgn),
    })
    return out


def _mx(a, b, k, f=max):
    xs = [x[k] for x in (a, b) if x.get(k) is not None]
    return f(xs) if xs else None


def worst(a, b):
    return {
        "kind": a.get("kind", "step"), "size": min(a["size"], b["size"]),
        "rise": None if (a["rise"] is None or b["rise"] is None) else max(a["rise"], b["rise"]),
        "reached": a["reached"] and b["reached"], "os": max(a["os"], b["os"]),
        "settle": max(a["settle"], b["settle"]), "settled": a["settled"] and b["settled"],
        "sse": max(a["sse"], b["sse"]), "osc": max(a["osc"], b["osc"]),
        "fb_std": max(a["fb_std"], b["fb_std"]), "pid_std": max(a["pid_std"], b["pid_std"]),
        "sat": max(a["sat"], b["sat"]), "wrong": a["wrong"] or b["wrong"],
        "lag": _mx(a, b, "lag"), "lag_ms": _mx(a, b, "lag_ms"), "lag_end": _mx(a, b, "lag_end"),
        "drive": _mx(a, b, "drive"), "behind": bool(a.get("behind") or b.get("behind")),
        "vtop": _mx(a, b, "vtop", min),
    }


def fmt1(r):
    """One move, one direction."""
    if r.get("kind") == "ramp":
        head = (f"lag {r['lag_ms']:.0f} ms ({max(0.0, r['lag']):.1f} counts)" if r.get("lag_ms") is not None
                else "lag -")
        if r.get("behind"):
            head += ", falls behind"
    else:
        head = f"rise {r['rise']:.0f} ms" if r["rise"] is not None else "never got to 90%"
    return (f"{head}, overshoot {r['os']:.0f}%, settle {r['settle']:.0f} ms, off by {r['sse']:.1f}, "
            f"ringing {r['osc']}")


def dir_order(names):
    """Directions in reading order: up before down, left before right, higher before lower."""
    return [-1, 1] if names.get(-1) in ("up", "left") else [1, -1]


def fmt(r, names=None):
    """A test: both ways when it has them (page 2.5: each direction on its own), then the shared figures."""
    if names and r.get("dp") and r.get("dm"):
        by = {1: r["dp"], -1: r["dm"]}
        s = " | ".join(f"{names[d]}: {fmt1(by[d])}" for d in dir_order(names))
    else:
        s = fmt1(r)
    s += f" | hold noise {r['fb_std']:.2f}, pid noise {r['pid_std']:.1f}"
    if r.get("seat_os") is not None:
        s += f" | seat {r['seat_deg']:.2f}°, overshoot {r['seat_os']:.0f}%, ringing {r['seat_osc']}"
    return s


def _slim(r):
    """A move's figures for the page's gauges and chart."""
    if not r:
        return None
    out = {}
    for k in ("kind", "lag_ms", "lag", "rise", "os", "settle", "settled", "sse", "osc", "drive", "sat", "behind",
              "reached", "fb_std", "pid_std", "v"):
        v = r.get(k)
        out[k] = round(v, 2) if isinstance(v, float) else v
    return out


SEAT_OS_SLACK = 10      # % the seat may overshoot beyond the motor before it counts against a setting


def kg_text(kg, unit):
    return f"{kg / 0.45359237:.0f} lb" if unit == "lb" else f"{kg:.0f} kg"


class Tuner:
    def __init__(self, board, gen):
        self.board, self.gen = board, gen
        self.state = "idle"            # idle | running | done | aborted | error
        self.mode = "tune"             # tune | check (page 2.5: test the current values, change nothing)
        self.stage = ""
        self.progress = 0
        self.lines = []
        self.result = None
        self.motor = None
        self.original = None           # the settings before the last auto-tune (Revert), and its motor
        self.orig_motor = None
        self.abort_flag = False
        self.applied = False
        self.recent = collections.deque(maxlen=1500)   # (time, target) sent - 15 s and more (see _check)
        self.hist = collections.deque(maxlen=200)
        self.cur = 512
        self.last_cmd = 0.0
        self.chk_seq = 0
        self.interf = 0
        self.rev = False
        self.t_start = 0.0
        self.runaway_limit = 400
        self.lo, self.hi = 100, 923              # where targets may go: Clip window + travel limits (firmware 1.9)
        self.events = None
        self.noise_sd = 0.5                      # the pot's noise at rest (1 sigma, counts), measured at the start
        self.stop_noisy = False                  # 2.9.2: stop when the noise needs a dead zone over 4
        self.fwin = collections.deque(maxlen=5)  # the last 5 pot readings: per-reading checks use their median (2.4.1)
        self.ramp_v = None                       # test moves follow a ramp at this speed (counts/s, page 2.5)
        self.dn = {1: "higher", -1: "lower"}     # what each direction is called on this rig
        self.live = {}                           # what the page's gauges show
        self.countdown = None
        self.rider_f = 0.0
        self.pr = {}
        self.slock = threading.Lock()            # two quick Starts can't both get through
        self.moved = False                       # this run has sent a target that differs from where it began
        self.start_t = None                      # the target when the run began
        self.quiet_until = 0.0                   # the wrong-way watch rests until then (getting into the seat)
        self.away_since = None                   # board ms when the wrong-way watch first saw "moving away" (2.6)
        self.load = None                         # 2.9.1: {"pull": +-1, "need": PWM} - the way the load pulls this
                                                 # motor and the drive that moves it against that, from the PWMmin step
        self.load_said = False
        self.pwm_now = (0, 255)                  # PWMmin, PWMmax last sent to the motor being tuned
        self.cur_p = None                        # the motor's values (check mode: what to keep)
        self.link_trouble_at = 0.0               # when a test move last had to be repeated (WiFi, page 2.7.2)

    # ---- public ----
    def running(self):
        return self.state == "running"

    def status(self):
        return {"state": self.state, "mode": self.mode, "motor": None if self.motor is None else self.motor + 1,
                "stage": self.stage, "progress": self.progress, "log": self.lines[-300:],
                "result": self.result, "can_revert": bool(self.original) and not self.running(),
                "revert_motor": None if self.orig_motor is None else self.orig_motor + 1,
                "live": self.live, "countdown": self.countdown,
                "motors": [m + 1 for m in getattr(self, "jm", [])] if self.mode == "joint" else None}

    def start(self, motor, amp, style, do_friction, do_ki, do_kd, rider="empty", rider_kg=0.0, unit="lb",
              mode="tune", stop_noisy=False):
        with self.slock:
            if self.running():
                return False, "An auto-tune is already running."
            if not self.board.connected:
                return False, "The board is not connected."
            if self.board.pending_restore:
                return False, ("The page is still putting back the settings from the last auto-tune (the link dropped "
                               "during it) - try again in a few seconds.")
            self.motor, self.mode = motor, (mode if mode in ("check", "joint") else "tune")
            self.stop_noisy = bool(stop_noisy)           # 2.9.2: stop instead of capping the dead zone at 4
            if self.mode == "joint":                     # 2.9: every motor in use, together
                self.jm = list(range(int(self.board.cfg.get("motors") or 3)))
                if len(self.jm) < 2:
                    self.state = "idle"
                    return False, "The test together needs at least two motors in use (Settings, Rig layout)."
                self.motor = self.jm[0]
            self.conn0 = self.board.conn_id              # 2.8: a new connection mid-run (the USB bridge closed, the
                                                         # board restarted) ends the run - the board may not be as it was
            self.state, self.stage, self.progress = "running", "Starting", 0
            self.lines, self.result, self.abort_flag = [], None, False
            self.applied, self.countdown, self.live, self.ramp_v = False, None, {}, None
            self.moved, self.start_t, self.quiet_until, self.cur_p = False, None, 0.0, None
            if self.mode == "tune":
                self.original, self.orig_motor = None, None
        threading.Thread(target=self._thread,
                         args=(motor, amp, style, do_friction, do_ki, do_kd, rider, rider_kg, unit),
                         daemon=True).start()
        return True, "started"

    def abort(self):
        self.abort_flag = True

    def revert(self):
        if self.running() or not self.original:
            return False
        self._apply(self.original, self.orig_motor)
        self.say(f"Reverted motor {self.orig_motor + 1} to the settings it had before auto-tune.")
        return True

    # ---- helpers ----
    def say(self, msg):
        self.lines.append(time.strftime("%H:%M:%S ") + msg)
        log(f"[tune M{(self.motor or 0) + 1}] {msg}")

    def _apply(self, p, m=None):
        b = self.board
        m = self.motor if m is None else m
        b.cmd_word("DEF"[m], p["kp"])
        b.cmd_word("GHI"[m], p["ki"])
        b.cmd_word("JKL"[m], p["kd"])
        b.cmd_word("MNO"[m], max(1, p["ks"]))
        b.cmd_pair("PQR"[m], p["pwmmin"], p["pwmmax"])
        b.cmd_pair("VWX"[m], p["dz"], p["pwmrev"])
        if m == self.motor:
            self.applied = True
            self.pwm_now = (int(p["pwmmin"]), int(p["pwmmax"]))
            self._now(p)
        time.sleep(0.25)

    def _get_params(self):
        pr = self.board.read_params()
        n = self.motor + 1
        need = [f"Kp{n}", f"Ki{n}", f"Kd{n}", f"Ks{n}", f"PWM{n}", f"DZ{n}", f"LIM{n}"]
        if any(k not in pr for k in need):
            raise TuneAbort(f"Couldn't read motor {n}'s settings from the board. Try again.", "refuse")
        self.pr = pr
        p = {"kp": pr[f"Kp{n}"], "ki": pr[f"Ki{n}"], "kd": pr[f"Kd{n}"], "ks": pr[f"Ks{n}"],
             "pwmmin": pr[f"PWM{n}"][0], "pwmmax": pr[f"PWM{n}"][1],
             "dz": pr[f"DZ{n}"][0], "pwmrev": pr[f"DZ{n}"][1],
             "lim": pr[f"LIM{n}"][0], "clip": pr[f"LIM{n}"][1]}
        return p, pr.get("FW")

    # ---- what the page's gauges show (page 2.5) ----
    def _lv(self, **kw):
        """Update the gauges' data. The page reads it from another thread, so it is never changed in place: each
        update is a new dict, swapped in at once."""
        self.live = dict(self.live, **kw)

    def _phase(self, key, stage=None, progress=None):
        self._lv(phase=key)
        if stage is not None:
            self.stage = stage
        if progress is not None:
            self.progress = progress

    def _now(self, p):
        self._lv(now={k: p.get(k) for k in ("kp", "ki", "kd", "ks", "pwmmin", "pwmmax", "dz")})

    def _show(self, label, r, kind="big"):
        """The latest test, each way, for the gauges."""
        self._lv(last={"label": label, "kind": kind, "move": r.get("kind"),
                       "p": _slim(r.get("dp") or r), "m": _slim(r.get("dm") or r),
                       "fb_std": round(r["fb_std"], 2), "pid_std": round(r["pid_std"], 2),
                       "seat_os": r.get("seat_os")}, n=self.live.get("n", 0) + 1)

    def _directions(self, m):
        """What 'towards higher counts' means on this rig: up/down for a lift (higher numbers lift the seat unless
        the full check saw otherwise; mirrored with REVERSE_MOTOR1), right/left for the rear slide."""
        cfg = self.board.cfg
        if m == tl_motor(cfg):
            d = 1 if int(cfg.get("tl_dir") or 1) > 0 else -1
            names = {d: "right", -d: "left"}
            sym = {d: "▶", -d: "◀"}
            kind = "slide"
        else:
            seen = (cfg.get("lift_dir") or {}).get(str(m + 1))
            sink = (cfg.get("lift_sink") or {}).get(str(m + 1))
            if seen in (1, -1, "1", "-1"):
                d = 1 if int(seen) > 0 else -1
            elif sink in (1, -1, "1", "-1"):                   # 2.6: up is away from where its corner sinks
                d = -1 if int(sink) > 0 else 1
            else:
                d = -1 if self.rev else 1
            names = {d: "up", -d: "down"}
            sym = {d: "▲", -d: "▼"}
            kind = "lift"
        return self._set_dirs(names, sym, kind)

    def _set_dirs(self, names, sym, kind):
        self.dn = names
        self._lv(dirs={"kind": kind, "p": {"name": names[1], "sym": sym[1]},
                       "m": {"name": names[-1], "sym": sym[-1]},
                       "order": ["p" if d == 1 else "m" for d in dir_order(names)]})
        return names

    def _load_labels(self, pull):
        """2.9.1: on a lift, a seat that sinks by itself sinks DOWN. When the PWMmin step saw it sink towards what
        this run calls "up", the directions are the wrong way round (a full check answered the other way, or the
        default): say so, and call them the other way for the rest of the run. The saved answer is left alone."""
        if self.dn.get(pull) != "up":
            return
        cfg, n = self.board.cfg, self.motor + 1
        ans = (cfg.get("lift_dir") or {}).get(str(n))
        src = ("your answer in the Diagnostics full check" if ans in (1, -1, "1", "-1") else
               "what was assumed (the Diagnostics full check asks which way the seat goes)")
        hl = "higher" if pull > 0 else "lower"
        self.say(f"The seat's weight pulls this corner towards {hl} numbers, so here {hl} numbers are DOWN - the other "
                 f"way round from {src}. The rest of this run calls them so. Worth answering the full check's "
                 f"direction question again (drag the motor's knob with the seat empty and watch which way the corner "
                 f"goes): the seat views go by that answer.")
        d = -pull
        self._set_dirs({d: "up", -d: "down"}, {d: "▲", -d: "▼"}, "lift")

    def _kp_hold(self, pwmmin, e_ok):
        """2.9.1: the Kp at which the P term adds, e_ok counts off target, what moving against the load took in the
        PWMmin step on top of this PWMmin (the board drives PWMmin + Kp x error / 128). 0 without a load."""
        if not self.load:
            return 0
        extra = max(0, self.load["need"] - pwmmin)
        return int(math.ceil(128.0 * extra / e_ok))

    def _load_wins(self, sg, win):
        """2.9.1: moving away from the target is the load winning, not a wiring fault, when it moves the way the
        PWMmin step saw the load pull it while the drive against it is still below what moved it against the load
        there (with a margin). A motor wired backwards goes the wrong way both ways, and that step stops on it; the
        runaway and travel limits still watch this one."""
        ld = self.load
        if not ld or -sg != ld["pull"]:
            return False
        pmin, pmax = self.pwm_now
        drive = max(min(abs(h[3]) + pmin, pmax) for h in win)
        if drive >= 1.25 * ld["need"] + 6:
            return False
        if not self.load_said:
            self.load_said = True
            n = self.motor + 1
            self.say(f"Motor {n} is sinking {self.dn[ld['pull']]} ({'higher' if ld['pull'] > 0 else 'lower'} counts) "
                     f"while it is driven the other way with PWM {drive:.0f} - less than the {ld['need']} it took to "
                     f"move it against the load in the PWMmin step, so that is the load winning, not a wiring fault.")
        return True

    # ---- moving ----
    def _cmd_value(self, v_int):
        return 1023 - v_int if self.rev else v_int

    def set_target(self, v_int):
        v_int = int(max(self.lo, min(self.hi, round(v_int))))
        self.board.cmd_word("ABC"[self.motor], self._cmd_value(v_int))
        if self.start_t is not None and v_int != self.start_t:
            self.moved = True
        self.cur = v_int
        self.last_cmd = time.time()
        self.recent.append((self.last_cmd, v_int))

    def _fb(self):
        s = self.board.latest()
        return s["m"][self.motor]["f"] if s else 512.0

    def _fb_med(self, n=9):
        """Median of the last n pot readings (~90 ms): a noisy pot can't fake a movement with one reading."""
        with self.board.slock:
            snap = list(self.board.samples)[-n:]
        fs = [x["m"][self.motor]["f"] for x in snap]
        return statistics.median(fs) if fs else 512.0

    def _calm(self, k, mult=1.5):
        """'Holds still' limit for the pot's spread while holding: k counts for a quiet pot, mult x its noise for a
        noisy one (a pot that reads +-2 counts at rest can't hold within +-2 on the graph either)."""
        return max(k, mult * self.noise_sd)

    def _t(self):
        s = self.board.latest()
        return s["m"][self.motor]["t"] if s else self.cur

    def wait(self, sec):
        end = time.time() + sec
        while True:
            self.board.hold_page()                         # SimHub waits while auto-tune runs (firmware 1.9)
            self._check()
            if time.time() - self.last_cmd > 0.8:          # keep-alive: holds full power on firmware 1.4
                if self.mode == "joint":
                    for m in self.jm:
                        self._jset(m, self.jcur[m])
                else:
                    self.set_target(self.cur)
            if time.time() >= end:
                return
            time.sleep(0.05)

    def _check(self):
        if self.mode == "joint":
            return self._jcheck()
        m, n = self.motor, self.motor + 1
        if self.abort_flag:
            raise TuneAbort("Stopped by you.")
        if not self.board.connected:
            raise TuneAbort("Lost the connection to the board.")
        if self.board.conn_id != getattr(self, "conn0", self.board.conn_id):
            raise TuneAbort("The connection to the board changed during the run (the USB bridge closed, or the "
                            "board restarted).")
        new = self.board.since(self.chk_seq)
        if not new:
            return
        self.chk_seq = new[-1]["seq"]
        now = time.time()
        # Targets this page sent in the last 15 s count as its own: when the board's WiFi module stalls, the page's
        # targets wait and then arrive in a burst, so the board can show one sent seconds ago (2.7.1 allowed 2 s and
        # took that for SimHub). On firmware 1.9 SimHub is held back during the run anyway ([kH], hold_page).
        allowed = {v for t, v in self.recent if now - t < 15.0} | {self.cur}
        lo_ok, hi_ok = self.lo - 25, self.hi + 25
        for s in new:
            mm = s["m"][m]
            self.fwin.append(mm["f"])
            fmed = statistics.median(self.fwin)                # a glitchy pot reading can't end the tune
            if s["dis"][m]:
                raise TuneAbort(f"Motor {n} was shut off by its safety cutoff (feedback went past Max limit).",
                                "unsafe")
            if s["low"] and now - self.t_start > 4:
                raise TuneAbort("The board is still in low-power mode although this page is sending targets. "
                                "Auto-tune needs firmware 1.4 on the board.", "refuse")
            if mm["t"] in allowed:
                self.interf = 0
            else:
                self.interf += 1
                if self.interf >= 6:
                    raise TuneAbort(f"Something else is moving motor {n} (SimHub?). Stop SimHub's motion "
                                    f"output and start again.")
            if abs(mm["t"] - fmed) > self.runaway_limit:
                raise TuneAbort(f"Motor {n} ran away from its target - most likely the motor or the pot is wired "
                                f"backwards (or the pot slipped on its shaft).", "unsafe")
            if fmed < lo_ok or fmed > hi_ok:
                raise TuneAbort(f"Motor {n} went outside its allowed travel ({fmed:.0f}).")
            self.hist.append((s["ms"], mm["f"], mm["t"] - mm["f"], mm["p"]))
        # wrong-direction watch: pushing towards the target for 250 ms but moving away from it (the median of the
        # first and last few readings, and more than the pot's noise - one noisy reading can't trigger it). It rests
        # while someone gets into the seat: their weight can push a lift away from where it holds (page 2.5).
        if now < self.quiet_until:
            self.hist.clear()
            self.away_since = None
        elif len(self.hist) > 2:
            t_end = self.hist[-1][0]
            win = [h for h in self.hist if t_end - h[0] <= 300]
            away = False
            if len(win) >= 10 and t_end - win[0][0] >= 250:
                es = [h[2] for h in win]
                if all(abs(e) > 30 for e in es) and (all(e > 0 for e in es) or all(e < 0 for e in es)):
                    sg = 1 if es[0] > 0 else -1
                    pushing = all(h[3] * sg > 15 for h in win)
                    fw = _hampel([h[1] for h in win])        # 2.5: a cluster of glitchy readings can't fake it
                    moved = (statistics.median(fw[-7:]) - statistics.median(fw[:7])) * sg
                    away = pushing and moved < -max(10.0, 3.0 * self.noise_sd)
                    if away and self._load_wins(sg, win):
                        away = False
            # 2.6: only when it is still so 150 ms later - a cluster of glitchy readings at one end of the window has
            # moved out of it by then; a motor wired backwards is still running away
            if not away:
                self.away_since = None
            elif self.away_since is None:
                self.away_since = t_end
            elif t_end - self.away_since >= 150:
                raise TuneAbort(f"Motor {n} moves AWAY from where it is driven. The motor or the pot is wired "
                                f"backwards.", "unsafe")

    def _ramp_move(self, x, v, ease=0.12):
        """Move the target to x at v counts/s, easing in and out over ~0.12 s: a test move the motor can follow, like
        a game's (page 2.5 - 2.4.1 and older jumped the target, so every test ran the motor flat out). The target is
        updated 50 times a second from the clock."""
        x = int(max(self.lo, min(self.hi, round(x))))
        x0 = float(self.cur)
        d = x - x0
        if abs(d) < 1.0 or v <= 0:
            self.set_target(x)
            return
        a = v / ease
        ta = v / a
        if a * ta * ta >= abs(d):                         # too short to reach full speed: accelerate, then brake
            ta, tc, vp = math.sqrt(abs(d) / a), 0.0, None
            vp = a * ta
        else:
            tc, vp = (abs(d) - a * ta * ta) / v, v
        total = 2 * ta + tc
        t_start = time.time()
        while True:
            t = time.time() - t_start
            if t >= total:
                break
            if t < ta:
                s = 0.5 * a * t * t
            elif t < ta + tc:
                s = 0.5 * a * ta * ta + vp * (t - ta)
            else:
                td = total - t
                s = abs(d) - 0.5 * a * td * td
            self.set_target(x0 + math.copysign(s, d))
            self._check()
            time.sleep(0.02)
        self.set_target(x)

    def _ramp_to(self, x, speed=160.0):
        self._ramp_move(x, speed)

    def _settle(self, x, timeout, tol=None):
        tol = tol if tol is not None else max(4.0, 1.5 * self.noise_sd)
        end = time.time() + timeout
        while time.time() < end:
            self.wait(0.1)
            if abs(self._fb_med(5) - x) <= tol:
                self.wait(0.2)
                return True
        return False

    def _move(self, x, hold, p, ramp=True, speed=None):
        """One test move to x: along a ramp at the measured test speed (ramp=True), or a jump of the target (small
        road-sized moves, and the top-speed check). A move the WiFi spoiled - the telemetry stopped for a moment, or
        the targets arrived bunched up, so the ramp wasn't the ramp - goes back to where it started and is done again
        (up to three times), instead of stopping auto-tune or measuring a lag that was the WiFi's (page 2.7.2)."""
        t_old = self._t()
        for attempt in range(4):
            r, why = self._move_once(x, hold, p, ramp, t_old, speed)
            if not why:
                return r
            if attempt == 3:
                raise TuneAbort(f"The WiFi link to the board kept stalling during the test moves ({why}). Put the "
                                f"board closer to the WiFi router (or an access point), or update the board's WiFi "
                                f"module (Arduino IDE, Tools, Firmware Updater), then try again.")
            self.link_trouble_at = time.time()
            self.say(f"WiFi hiccup during that move ({why}) - doing it again.")
            if self.events:
                self.events.add("tune", f"Auto-tune repeated a test move of motor {self.motor + 1}: {why}.", quiet=True)
            if speed:
                self._ramp_move(t_old, speed, ease=QUICK_EASE)
            elif ramp and self.ramp_v:
                self._ramp_move(t_old, self.ramp_v)
            else:
                self.set_target(t_old)
            self.wait(max(0.8, hold))
            self._settle(t_old, 3.0)              # back where it started, and at rest, before it goes again

    def _link_trouble(self, got, seq0, t_old, x, page_ms, elapsed_ms):
        """Why a test move's telemetry can't be trusted, or None: a gap in the board's readings, readings that stop
        short of now (a stall still going on), or (a ramp) targets that reached the board far faster or slower than
        the page sent them."""
        before = [s for s in got if s["seq"] <= seq0][-1:]       # the last reading before the move was sent
        after = [s for s in got if s["seq"] > seq0]
        if len(after) < 10:
            return "no telemetry arrived"
        seen = before + after
        gap = max((b["ms"] - a["ms"] for a, b in zip(seen, seen[1:])), default=0)
        if gap > 400:                          # (a few hundred ms now and then is normal and harmless)
            return f"the board's readings stopped for {gap / 1000:.1f} s"
        short = elapsed_ms - (after[-1]["ms"] - seen[0]["ms"])
        if short > 500:
            return f"the board's readings stopped {short / 1000:.1f} s ago"
        m = self.motor
        i0 = next((i for i, s in enumerate(after) if s["m"][m]["t"] != t_old), None)
        if i0 is not None and after[i0]["ms"] - seen[0]["ms"] > 400:
            return f"the move reached the board {(after[i0]['ms'] - seen[0]['ms']) / 1000:.1f} s late"
        if page_ms:
            i1 = next((i for i, s in enumerate(after) if s["m"][m]["t"] == x and i0 is not None and i >= i0), None)
            if i0 is None or i1 is None:
                return "the move's targets didn't show up in the telemetry"
            board_ms = after[i1]["ms"] - after[i0]["ms"]
            if board_ms < 0.5 * page_ms - 40 or board_ms > page_ms + 500:
                return (f"the targets reached the board bunched up: a {page_ms / 1000:.2f} s ramp took "
                        f"{board_ms / 1000:.2f} s there")
        return None

    def _move_once(self, x, hold, p, ramp, t_old, speed=None):
        seq0 = self.board.seq
        t_begin = time.time()
        page_ms = None
        if speed:
            t0 = time.time()
            self._ramp_move(x, speed, ease=QUICK_EASE)
            page_ms = (time.time() - t0) * 1000.0
        elif ramp and self.ramp_v:
            t0 = time.time()
            self._ramp_move(x, self.ramp_v)
            page_ms = (time.time() - t0) * 1000.0
        else:
            self.set_target(x)
        self.wait(hold)
        self.wait(0.15)                       # let the last telemetry burst arrive
        # from 30 readings before the move on: where it starts is the median of 15 readings at rest (2.4.1 had only
        # the 2-4 that arrived before the target first changed, and a cluster of glitches could be most of them)
        got = despike(self.board.since(seq0 - 30), self.motor)
        why = self._link_trouble(got, seq0, t_old, x, page_ms if page_ms and page_ms > 150 else None,
                                 (time.time() - t_begin) * 1000.0)
        if why:
            self.link_trouble_at = time.time()
            return None, why
        r = analyze_move(got, self.motor, t_old, p["pwmmin"], p["pwmmax"], hold * 1000 - 100, self.noise_sd, seq0)
        if r is None:
            return None, "the move didn't show up in the telemetry"
        seat = seat_step(self.board.since(seq0 - 20), self.motor, t_old,      # motion sensor: what the seat did
                         yaw=self.motor == tl_motor(self.board.cfg),         # (traction loss: how it turned)
                         whole=bool(ramp and self.ramp_v))                   # a gradual move: all of it
        if seat and not seat.get("small") and seat.get("overshoot") is not None:
            r.update(seat_os=seat["overshoot"], seat_osc=seat["ringing"], seat_deg=seat["deg"],
                     seat_dpc=seat.get("deg_per_count"))
        if r["wrong"]:
            if time.time() - self.link_trouble_at < 10.0:
                # right after a WiFi hiccup the motor can still be on its way back from the move before
                return None, "it set off the wrong way - probably still moving back after the last hiccup"
            raise TuneAbort(f"Motor {self.motor + 1} moved the wrong way. The motor or the pot is wired "
                            f"backwards.", "unsafe")
        return r, None

    def _hold(self):
        """How long a sweep test move holds at its end: 1.3 s, longer for a slow motor (down to 2.0 s at test moves of
        160 counts/s or slower) - at the low Kp the sweep starts with, a slow motor is still catching up after the
        move, and its creeping would look like a restless hold (page 2.6)."""
        v = self.ramp_v or 300
        return 1.3 if v >= 300 else round(min(2.0, 1.3 + (300 - v) / 200.0), 2)

    def _first_way(self):
        """Which way a test sets off: up for a lift (whichever way its numbers run), right for the rear slide."""
        return -1 if self.dn.get(-1) in ("up", "right") else 1

    def _test_set(self, c, A, p, hold=1.6, ramp=True):
        """One test (page 2.6): from the start position c out and back each way - up, back to the start, down, back
        to the start (right and left for the rear slide), as you move a knob on the dashboard - so the seat never
        goes further than A from where it started, and each direction is measured twice: moving away from the start
        and coming back to it. (2.5 went from the bottom of the travel to the top and back, so every test seemed to
        start by going down.) The result is the worst of the four moves, with each direction's worse move under 'dp'
        (towards higher counts) and 'dm' (lower)."""
        first = self._first_way()
        moves = [self._move(x, hold, p, ramp) for x in (c + first * A, c, c - first * A, c)]
        towards = {first: (moves[0], moves[3]), -first: (moves[1], moves[2])}
        dp, dm = worst(*towards[1]), worst(*towards[-1])
        r = worst(dp, dm)
        r["dp"], r["dm"] = dp, dm
        seats = [x for x in moves if x.get("seat_os") is not None]
        if seats:
            # with the motion sensor, the seat's own overshoot and ringing count too: a setting that keeps the motor
            # calm but makes the frame bounce isn't calm
            r.update(motor_os=r["os"], motor_osc=r["osc"], seat_os=max(x["seat_os"] for x in seats),
                     seat_osc=max(x["seat_osc"] for x in seats), seat_deg=max(x["seat_deg"] for x in seats),
                     seat_dpc=next((x["seat_dpc"] for x in seats if x.get("seat_dpc")), None))
            r["os"] = max(r["os"], r["seat_os"] - SEAT_OS_SLACK)
            r["osc"] = max(r["osc"], r["seat_osc"])
        return r

    def _safe_stop(self):
        p = dict(self.original or {})
        n = self.motor + 1
        if self.board.fwnum() >= 15:
            # switched off (it brakes and shows Off) and its own settings back, so Enable Motors is all it takes
            # once the cause is fixed - page 2.3.1 and older left it on with PWMmax 0, which looked "Online"
            self.board.cmd_text(f"di{n}")
            time.sleep(0.15)
            self._hold_here()                            # Enable Motors then holds it where it stopped
            if self.mode == "check":                     # the check changed nothing: its values are as they were
                self.say(f"SAFETY: motor {n} is switched off; its values are unchanged. Fix the cause first, then "
                         f"press Enable Motors.")
                return
            if self.original and self.orig_motor == self.motor:
                self._apply(self.original)
            self.say(f"SAFETY: motor {n} is switched off, with the settings it had before auto-tune. Fix the cause "
                     f"first, then press Enable Motors.")
            return
        if self.mode == "check" or self.orig_motor != self.motor:
            p = dict(self.cur_p or {})
        self.board.cmd_pair("PQR"[self.motor], 0, 0)
        self.board.cmd_pair("VWX"[self.motor], p.get("dz", 0), 0)
        self.say(f"SAFETY: motor {n}'s drive is set to zero (PWMmax 0, PWMrev 0) so it can't run away. This is "
                 f"NOT saved - power-cycling the board brings back the stored settings. Fix the cause first, "
                 f"then " + ("power-cycle the board." if self.mode == "check" else
                             "press Revert (or Enable motors if the cutoff tripped)."))

    def _hold_here(self):
        """Stop moving: the target becomes where the motor is - the median of its last readings (one glitchy
        reading must not become a target), and only if this run moved it at all."""
        try:
            if self.moved:
                self.set_target(self._fb_med(9))
        except Exception:
            pass

    def _restore_and_hold(self):
        """Stop the move, then put the settings back. False when the link to the board is gone (2.8): the page then
        sends them again as soon as it is back (main(), on_connect) - else the board would keep the test values."""
        self._hold_here()                                # first stop the move, then put the settings back
        if self.mode == "tune" and self.original and self.orig_motor == self.motor:
            self._apply(self.original)
            if not self.board.connected:
                self.board.pending_restore = {"motor": self.motor, "params": dict(self.original), "t": time.time()}
                return False
        return True

    def _countdown(self, secs):
        """'I'm in the seat': nothing moves until the countdown ends (Stop works all along)."""
        self._phase("countdown", "Get in the seat")
        self.say(f"Get in the seat now: the test starts in {secs} s. Stop (or Space / Esc on the page) ends it at "
                 f"any time.")
        end = time.time() + secs
        self.quiet_until = end + 2.0
        try:
            while True:
                left = end - time.time()
                if left <= 0:
                    break
                self.countdown = int(math.ceil(left))
                self.wait(min(0.25, left))
        finally:
            self.countdown = None

    def _pwmmin_search(self, p, sigma, n):
        """Step 2: the smallest drive that reliably moves the motor, each way. Returns {1: pwm up, -1: pwm down}.
        Starts with almost no drive, so the motor only creeps a few counts at a time. Movement is judged on the
        median of several readings against limits above the pot's noise; a motor that goes the wrong way is only
        called "wired backwards" when it does so BOTH ways - a seat that sinks under its own weight while the drive
        is still too weak to lift it goes the wrong way one way only (page 2.4)."""
        p.update(kp=20)
        found = {1: None, -1: None}
        wrong = {1: 0, -1: 0}                # times it went the wrong way when driven each way
        went_right = {1: False, -1: False}   # it moved the right way at least once
        sag_dir = None                       # the way the load pulls it, once that's clear
        thr_move = max(5.0, 2.5 * sigma)
        thr_wrong = max(6.0, 3.0 * sigma)
        step = int(max(12, round(2.0 * thr_move)))       # far enough that a move can show above the noise
        way = lambda d: f"{self.dn[d]} ({'higher' if d > 0 else 'lower'} counts)" if self.dn[d] not in (
            "higher", "lower") else f"{self.dn[d]} counts"
        cap = int(min(80, p["pwmmax"] - 5))
        pw = {"cap": cap, "trying": 0, "p": None, "m": None}
        for pm in range(0, cap + 1, 2):
            self.progress = 10 + int(20 * pm / max(1, cap))
            pw = dict(pw, trying=pm)
            self._lv(pwmmin=pw)
            p["pwmmin"] = pm
            self._apply(p)
            for d in (1, -1):
                if found[d] is not None:
                    continue
                ok = 0
                for _ in range(2):
                    self.wait(0.12)
                    f0 = self._fb_med()
                    self.set_target(round(f0) + d * step)
                    self.wait(0.6)
                    f1 = self._fb_med()
                    moved = (f1 - f0) * d
                    if moved <= -thr_wrong:
                        wrong[d] += 1
                        self.set_target(round(f1))          # stop pushing at once
                        if sag_dir != d:
                            self.say(f"Went {-moved:.0f} counts the wrong way when driven {way(d)} at PWM {pm} - "
                                     f"checking the other way before deciding.")
                        break
                    if moved >= thr_move:
                        ok += 1
                        went_right[d] = True
                    else:
                        break
                if ok == 2:
                    found[d] = pm
                    pw = dict(pw, **{"p" if d > 0 else "m": pm})
                    self._lv(pwmmin=pw)
                    self.say(f"Moves reliably {way(d)} at PWM {pm}.")
            # a motor wired backwards goes the wrong way BOTH ways
            if wrong[1] and wrong[-1]:
                raise TuneAbort(f"motor {n} moved the wrong way both ways (driven towards higher counts it went "
                                f"lower, and the other way round). The motor or the pot is wired backwards.",
                                "unsafe")
            for d in (1, -1):
                if wrong[d] and went_right[-d] and sag_dir is None:
                    sag_dir = d
                    self.say(f"It moves the right way {way(-d)}, so going the other way when driven {way(d)} is the "
                             f"load pulling it (the seat's weight, or the gearbox can be driven backwards) while the "
                             f"drive is still too weak - not a wiring fault. Carrying on with more drive.")
                if wrong[d] >= 3 and not went_right[-d]:
                    raise TuneAbort(f"motor {n} went the wrong way {wrong[d]} times when driven {way(d)} and hasn't "
                                    f"moved the right way yet. The motor or the pot may be wired backwards - run the "
                                    f"Diagnostics full check to see.", "unsafe")
            if found[1] is not None and found[-1] is not None:
                break
        if found[1] is None and found[-1] is None:
            raise TuneAbort(f"motor {n} didn't move even with PWMmin {cap}. Check motor power and wiring.")
        if found[1] is None or found[-1] is None:
            good = 1 if found[1] is not None else -1
            raise TuneAbort(f"motor {n} moves {way(good)} but not the other way even at PWM {cap}: too weak for "
                            f"the load with PWMmax {p['pwmmax']}, or something binds.")
        # 2.9.1: which way the load pulls it and what it takes to move it against that - the hold and the Kp sweep
        # that follow need a Kp that can hold it, and the wrong-direction watch must not take it sinking for a fault
        # (only when it went the wrong way at low drive: the load drives it backwards. A plain difference in
        # friction between the ways holds it still and changes nothing here.)
        if sag_dir is not None:
            pull = -sag_dir
            self.load = {"pull": pull, "need": int(found[-pull])}
            if self.dn.get(1) in ("up", "down"):
                self._load_labels(pull)
        return found

    def _measure_speed(self, p, c, A, share, change=True):
        """Top speed each way from one quick move each way (the target jumps; Kp 120-200 so the drive is at or near
        PWMmax for most of it): gently up by A from the start position, then a jump down to A below the start and
        one back up - the same 2A each way, so both are timed alike - then gently back to the start. The test moves
        then run at `share` of the slower way."""
        n = self.motor + 1
        q = dict(p)
        if change:              # the Kp the motor had before (the PWMmin search leaves a low one), within 120-200
            ref = (self.original or p)["kp"]
            q.update(kp=int(min(SPEED_KP[1], max(SPEED_KP[0], ref))), ki=0, kd=0, ks=1)
            self._apply(q)
        first = self._first_way()
        self._ramp_to(c + first * A)
        self._settle(c + first * A, 3.0)
        b = self._move(c - first * A, 1.6, q, ramp=False, speed=QUICK_V)    # the second way, timed over 2A
        a = self._move(c + first * A, 1.6, q, ramp=False, speed=QUICK_V)    # the first way, the same 2A
        self._ramp_to(c)
        self._settle(c, 2.0)
        v = {first: a.get("vtop") or 0.0, -first: b.get("vtop") or 0.0}
        if min(v.values()) < 15:
            slow = 1 if v[1] < v[-1] else -1
            raise TuneAbort(f"motor {n} hardly moves {self.dn[slow]} on a full move ({v[slow]:.0f} counts/s with "
                            f"PWMmax {p['pwmmax']}). Is motor power on, or is PWMmax far too low for the load?")
        vslow = min(v.values())
        ramp = int(round(share * vslow / 10.0)) * 10
        filt = self.pr.get("FILT")
        if isinstance(filt, list) and len(filt) > 1 and filt[1]:
            cap = int(0.9 * filt[1] * 100)               # the board's own max speed would slow the goal down
            if 0 < cap < ramp:
                ramp = cap
                self.say(f"The board's Max speed setting ({filt[1] * 100} counts/s) limits the test moves to "
                         f"{cap} counts/s.")
        slow_cap = int(A / RAMP_MIN_S / 10.0) * 10              # a short travel still gets a gradual move
        if 30 <= slow_cap < ramp:
            ramp = slow_cap
            self.say(f"Test moves capped at {slow_cap} counts/s, so a move of {A} counts still takes "
                     f"{RAMP_MIN_S:.1f} s.")
        self.ramp_v = int(max(30, min(1200, ramp)))
        self._lv(speed={"p": round(v[1]), "m": round(v[-1]), "ramp": self.ramp_v,
                        "share": round(share * 100), "pwmmax": p["pwmmax"]})
        o = dir_order(self.dn)
        self.say(f"Top speed{' (one quick move each way at Kp ' + str(q['kp']) + ', setting off over 0.2 s)' if change else ''}: "
                 + ", ".join(f"{self.dn[d]} {v[d]:.0f}" for d in o)
                 + f" counts/s with PWMmax {p['pwmmax']}. The test moves run at {self.ramp_v} counts/s "
                   f"({share * 100:.0f}% of the slower way), so the motor can follow them.")
        if max(v.values()) > 1.6 * vslow:
            self.say(f"Much slower {self.dn[1 if v[1] < v[-1] else -1]} than {self.dn[-1 if v[1] < v[-1] else 1]} - "
                     f"the load works against it that way.")
        return v

    # ---- the procedure ----
    def _thread(self, *a):
        final = "error"
        try:
            self.gen.stop_now()
            if self.mode == "check":
                self._run_check(*a)
            elif self.mode == "joint":
                self._run_joint(*a)
            else:
                self._run(*a)
            final = "done"
        except TuneAbort as e:
            final = "aborted"
            self.say(("Cannot start: " if e.kind == "refuse" else "Stopped: ") + str(e))
            try:
                if self.mode == "joint":
                    if e.kind != "refuse":
                        self._jstop(e.kind == "unsafe")
                elif e.kind == "unsafe":
                    self._safe_stop()
                elif e.kind == "refuse":
                    pass                                 # nothing was moved or changed: leave it all alone
                elif self.mode == "tune" and self.original and self.applied:
                    if self._restore_and_hold():
                        self.say("Previous settings restored; the motor holds where it is.")
                    else:
                        self.say("The link to the board is gone, so the previous settings couldn't be sent yet - the "
                                 "page sends them as soon as the board is back.")
                else:
                    self._hold_here()
            except Exception as e2:
                self.say(f"Couldn't put everything back ({e2!r}) - press Revert, or power-cycle the board.")
        except Exception as e:                                  # a bug - leave the rig as it was
            self.say(f"Internal error: {e!r}")
            try:
                if self.mode == "joint":
                    self._jstop(False)
                elif self.mode == "tune" and self.original:
                    self._restore_and_hold()
                else:
                    self._hold_here()
            except Exception:
                pass
        finally:
            self.stage, self.countdown = "", None
            try:
                self.board.release_page()                # SimHub may move the seat again
            except Exception:
                pass
            try:
                self._log_end(final)
            except Exception:
                pass
            self.state = final                           # last: a new run can't start before this one is logged

    def _log_end(self, state):
        if not self.events:
            return
        n = (self.motor or 0) + 1
        if self.mode == "joint":
            ms = "+".join(str(m + 1) for m in getattr(self, "jm", []))
            if state == "done" and self.result:
                self.events.add("tune", f"Test of motors {ms} together: " + (
                    "fine." if self.result.get("ok") else "; ".join(self.result.get("issues") or [])))
            else:
                last = next((l[9:] for l in reversed(self.lines) if "Stopped" in l or "Cannot" in l or "error" in l),
                            state)
                self.events.add("tune", f"Test of motors {ms} together {state}: {last}")
            return
        what = "Check of motor %d's values" % n if self.mode == "check" else f"Auto-tune of motor {n}"
        if state == "done" and self.result and self.mode == "tune":
            a, b = self.result["before"], self.result["after"]
            self.events.add("tune", f"Auto-tune of motor {n} finished: " + ", ".join(
                f"{k} {a[k]}->{b[k]}" for k in a if a[k] != b[k]) + " (not saved yet).", motor=n,
                before=a, after=b)
        elif state == "done" and self.result:
            self.events.add("tune", f"{what}: " + ("fine." if self.result.get("ok") else
                                                   "; ".join(self.result.get("issues") or [])), motor=n)
        else:
            last = next((l[9:] for l in reversed(self.lines) if "Stopped" in l or "Cannot" in l or "error" in l),
                        state)
            self.events.add("tune", f"{what} {state}: {last}", motor=n)

    def _prepare(self, m, amp, check=False):
        """Reads the motor's settings and works out where it may move. Returns (orig, c, lo, hi, A)."""
        b, n = self.board, m + 1
        self._phase("prep", "Reading settings", 2)
        orig, fw = self._get_params()
        if not fw or fw[1] < 14:
            raise TuneAbort("auto-tune needs firmware 1.4 or newer on the board (flash the newest SMC3_R4.ino).",
                            "refuse")
        self.rev = (m == 0 and bool(fw[0] & 1))
        self._directions(m)
        s = b.latest()
        if not s:
            raise TuneAbort("No telemetry from the board yet.", "refuse")
        if s["dis"][m]:
            raise TuneAbort(f"motor {n} is shut off - press 'Enable motors' first.", "refuse")
        self.lo, self.hi = b.window(m)
        c = b.centre(m)                          # 512, or the level seat with a seat set-up (firmware 1.9)
        room = min(c - self.lo, self.hi - c) - 60
        if room < 40:
            raise TuneAbort(f"the allowed travel ({self.lo}-{self.hi}, around {c}) is too narrow to test in.", "refuse")
        if orig["pwmmax"] < 30:
            raise TuneAbort(f"PWMmax is {orig['pwmmax']} - set it to at least 60 first.", "refuse")
        A = int(max(40, min(amp, room)))
        if A < amp:
            self.say(f"Travel limited to ±{A} by the allowed travel.")
        self.runaway_limit = 2 * A + 80
        self.cur = s["m"][m]["t"]
        self.start_t, self.moved, self.cur_p = self.cur, False, dict(orig)
        self.recent.clear(); self.hist.clear(); self.away_since = None
        self.load, self.load_said = None, False
        self.recent.append((time.time(), self.cur))
        self.chk_seq, self.interf, self.t_start = b.seq, 0, time.time()
        self._now(orig)
        if self.dn[1] in ("up", "down"):
            how = ("" if (b.cfg.get("lift_dir") or {}).get(str(n)) else
                   (" - from the last full check: this corner sank towards " +
                    ("higher" if self.dn[1] == "down" else "lower") + " numbers under the seat's weight"
                    if (b.cfg.get("lift_sink") or {}).get(str(n)) else
                    " - assumed, as SimHub expects; the Diagnostics full check asks which way the seat really goes"))
            ans = (b.cfg.get("lift_dir") or {}).get(str(n))
            snk = (b.cfg.get("lift_sink") or {}).get(str(n))
            if ans in (1, -1, "1", "-1") and snk in (1, -1, "1", "-1") and int(ans) == int(snk):
                # 2.6: the answer says higher numbers lift this corner, but it sank towards higher numbers
                how += (f" (your answer in the full check) - but in that check this corner sank towards "
                        f"{'higher' if int(snk) > 0 else 'lower'} numbers when its motor was switched off, which "
                        f"would make higher numbers DOWN. Worth a look: drag its knob with the seat empty")
            self.say(f"Directions: {self.dn[1]} = higher counts" +
                     (" (motor 1 is mirrored in the firmware)" if self.rev else "") + how + ".")
        elif self.dn[1] in ("right", "left"):
            self.say(f"Directions: higher counts move the rear to the {self.dn[1]}.")
        self._lv(travel=A)
        return orig, c, c - A, c + A, A

    def _noise(self, m, do_friction, p):
        """Pot noise at rest - every limit below that judges "holding still" or "moved" scales with it. 2.9.1: three
        readings of 1 s each instead of one of 1.5 s, and the middle one counts - noise that comes and goes (one
        reading came out 1.3 and the next 2.7 on the same rig) can't set every limit from one lucky or unlucky
        moment; how far they differ is said in the log."""
        b = self.board
        hall = hall_sensor(b.cfg)
        sn = "Sensor" if hall else "Pot"
        self._phase("noise", "Measuring pot noise", 8)
        self.wait(1.0)                           # let any ringing from the move die out first
        sig, plains, allr = [], [], []
        for _ in range(3):
            seq = b.seq
            self.wait(1.0)
            fs = [x["m"][m]["f"] for x in b.since(seq)]
            if len(fs) < 12:
                continue
            # noise = what's left after removing slow movement (5-sample moving average)
            resid = [fs[i] - _mean(fs[i - 2:i + 3]) for i in range(2, len(fs) - 2)]
            sig.append(_rstd(resid) * 1.12)      # 2.4.1: glitchy readings don't count as noise
            plains.append(_std(resid) * 1.12)
            allr += resid
        if not sig:
            raise TuneAbort("No telemetry from the board while measuring the pot noise.")
        sigma = statistics.median(sig)
        plain = _std(allr) * 1.12
        self.noise_sd = max(0.3, sigma)
        varies = len(sig) == 3 and max(sig) > 0.6 and max(sig) > 2.0 * max(0.15, min(sig))
        # 2.9.2: the dead zone that would cover the noise (3 sigma + 1), and the cap of 4 - a bigger dead zone would
        # cost accuracy on every move, so over the cap the tune says so (and stops, if asked to) instead of quietly
        # capping: the fix is the signal, not the dead zone
        want = int(max(1, math.ceil(3 * sigma) + 1))
        self._lv(noise={"sd": round(sigma, 2), "glitchy": plain > max(2.0, 2.0 * sigma),
                        "windows": [round(x, 2) for x in sig], "dz_wanted": want, "dz_cap": 4,
                        "capped": want > 4})
        if do_friction:
            p["dz"] = int(min(4, want))
            self.say(f"{sn} noise at rest ±{sigma:.2f} counts (three readings of 1 s: "
                     f"{', '.join(f'±{x:.2f}' for x in sig)}) -> dead zone {p['dz']}"
                     + (f" (capped: ±{sigma:.2f} would need {want} to cover it)." if want > 4 else "."))
        else:
            self.say(f"{sn} noise at rest ±{sigma:.2f} counts (three readings of 1 s: "
                     f"{', '.join(f'±{x:.2f}' for x in sig)}).")
        if want > 4:
            self.say(f"NOISY INPUT: ±{sigma:.2f} counts would need a dead zone of {want} to keep the motor still"
                     + (", and the tune caps it at 4 (a bigger one costs accuracy on every move)" if do_friction else
                        f" (yours stays {p.get('dz', '-')}, as asked)")
                     + f". Expect the motor to tick or hunt while holding. The fix is the signal, not the dead zone: "
                     f"Diagnostics, Sensor check (A, B and C) shows whether it is the {sn.lower()} side, the motor "
                     f"supply or the drive."
                     + ("" if self.stop_noisy else " Tick 'Stop if too noisy' in the auto-tune settings to have the "
                                                  "tune stop here instead."))
            if self.stop_noisy:
                raise TuneAbort(f"Stopped: the {sn.lower()} is too noisy to tune well (±{sigma:.2f} counts needs a "
                                f"dead zone of {want}, over the cap of 4). Fix the signal first - Diagnostics, "
                                f"Sensor check A / B / C tells where it comes from - or untick 'Stop if too noisy' "
                                f"to tune anyway with dead zone 4.")
        if varies:
            self.say("The noise comes and goes (the readings differ more than twice over): the limits below use the "
                     "middle one, and the Kp sweep checks restless holds against a gentler Kp before believing them. "
                     "Diagnostics, Sensor check shows what it does over 10 s.")
        if sigma > 1.5:
            if hall:
                self.say("That's noisy for a contactless sensor: the tests below allow for it. It has no wiper, so look "
                         "at its 5 V and GND wiring (not shared with the motor bridges), the signal wire (shielded, "
                         "away from the motor cables) and the filter at the Arduino.")
            else:
                self.say("That's a noisy pot (usual is ±0.3-1): the tests below allow for it. A 100 nF capacitor from "
                         "the pot's wiper to GND at the Arduino, and pot wires kept away from the motor wires, usually "
                         "fix it.")
        if plain > max(2.0, 2.0 * sigma):
            self.say(f"The {sn.lower()} also glitches: now and then a reading far off (spread ±{plain:.1f} with them). "
                     f"The tests below ignore them, but the motor reacts to every one - check the "
                     + ("sensor's wiring, its 5 V / GND and every joint and connector" if hall else
                        "pot's wiring and connector") + " (Diagnostics, Sensor check counts them).")
        return sigma

    def _run(self, m, amp, style, do_friction, do_ki, do_kd, rider="empty", rider_kg=0.0, unit="lb"):
        b, n = self.board, m + 1
        os_t, margin, knee_tol, lag_t = STYLES.get(style, STYLES["normal"])
        os_0, lag_0 = os_t, lag_t
        self.noise_sd = 0.5
        seated = rider == "seated"
        fr = 0.0 if seated else max(0.0, min(1.5, float(rider_kg or 0) / RIDER_REF_KG))
        self.rider_f = fr
        share = RAMP_SHARE - 0.1 * min(1.0, fr)
        keys = [k for k, _ in PHASES if (k != "countdown" or seated) and (k != "pwmmin" or do_friction)
                and (k != "ki" or do_ki) and (k != "kd" or do_kd)]
        self._lv(phases=[[k, l] for k, l in PHASES if k in keys], style=style,
                 rider={"mode": "seated" if seated else "empty", "kg": rider_kg, "unit": unit})
        who = (" - you in the seat" if seated else
               (f" - seat empty, allowing for a rider of {kg_text(rider_kg, unit)}" if fr > 0 else " - seat empty"))
        self.say(f"Auto-tune motor {n}, style '{style}', travel ±{amp} counts{who}.")
        if fr > 0:
            f1 = min(1.0, fr)
            os_t, lag_t = os_t * (1 - 0.35 * f1), lag_t * (1 - 0.25 * f1)
            self.say(f"Allowing for the rider's weight: overshoot limit {os_t:.1f}% instead of {os_0:.0f}% (the extra "
                     f"weight carries further), follow within {lag_t:.0f} ms instead of {lag_0:.0f} (it is slower "
                     f"with you in it), test moves at {share * 100:.0f}% of top speed instead of {RAMP_SHARE * 100:.0f}%"
                     + (", and a little Ki is kept for the weight" if do_ki else "") +
                     f". These are estimates - run Check with you in the seat afterwards.")
        sse_ok0 = None
        self._lv(targets={"lag_ms": round(lag_t), "os": round(os_t, 1), "settle": SETTLE_OK_MS, "sse": None,
                          "pid": PID_NOISE_MAX})

        orig, c, lo, hi, A = self._prepare(m, amp)
        self.original, self.orig_motor = dict(orig), m
        if seated:
            self._countdown(COUNTDOWN_S)

        p = dict(orig)
        p.update(kp=80, ki=0, kd=0, ks=1, dz=max(1, orig["dz"]))
        self._apply(p)

        # 1. centre and noise
        self._phase("prep", "Moving to centre", 5)
        self._ramp_to(c)
        self._settle(c, 4.0, tol=max(4.0, p["dz"] + 2))
        if abs(self._fb_med() - c) > 40:
            raise TuneAbort(f"motor {n} didn't follow the target (feedback {self._fb_med():.0f}, wanted {c}). "
                            f"Is motor power on?")
        sigma = self._noise(m, do_friction, p)
        self._now(p)
        sse_ok0 = p["dz"] + 3.0
        self._lv(targets=dict(self.live["targets"], sse=sse_ok0))
        if do_friction:
            # 2. PWMmin: smallest drive that reliably moves the motor, per direction
            self._phase("pwmmin", "Finding the minimum drive (PWMmin)", 10)
            self.say("Finding the minimum drive: it starts with almost none, so the motor only creeps a few counts at a "
                     "time.")
            found = self._pwmmin_search(p, sigma, n)
            p["pwmmin"] = min(found[1], found[-1])
            gap = abs(found[1] - found[-1])
            easy = 1 if found[1] <= found[-1] else -1
            if self.load:
                # 2.9.1: a seat that sinks by itself needs no drive at all the easy way - that is its weight, not
                # the motor's friction. With PWMmin 0 (2.9.1b2/b3) it hung well below where it was sent (on the rig
                # 45 counts at Kp 193, read as 11% overshoot down, and the sweep stopped "too lively"): Kp alone had
                # to lift it. Most of what lifting took goes into PWMmin instead, as on a motor that doesn't sink.
                lift = self.load["need"]
                p["pwmmin"] = int(max(found[easy], min(round(0.8 * lift), int(0.6 * p["pwmmax"]))))
                self.say(f"PWMmin {p['pwmmin']}: the seat sinks by itself, so going {self.dn[easy]} needs no drive - "
                         f"that is its weight, not the motor's friction. With PWMmin {found[easy]} it would hang well "
                         f"below where it is sent and Kp alone would have to lift it; {p['pwmmin']} is 80% of the "
                         f"{lift} lifting took, so small corrections {self.dn[-easy]} need little more from Kp.")
            else:
                self.say(f"PWMmin {p['pwmmin']} (the easier way, {self.dn[easy]}; {self.dn[-easy]} needs "
                         f"{max(found.values())}).")
            if gap > 15 and not do_ki:
                do_ki = True
                self.say(("Large difference between directions (friction or binding in the rear slide, or the "
                          "seat pulling to one side) - " if self.motor == tl_motor(self.board.cfg) else
                          "Large difference between directions (typical with a worm gear lifting your weight) - ")
                         + "the Ki step will run to make up for it.")
            if self.load:
                # 2.9.1: the step leaves Kp 20 - with the easier way's PWMmin that can't hold a seat that sinks by
                # itself (it sank while the PID pushed, and 2.9.1b1 called that wired backwards)
                kh = min(400, max(80, self._kp_hold(p["pwmmin"], 40.0)))
                if kh > p["kp"]:
                    p["kp"] = kh
                    self.say(f"Holding with Kp {kh} until the Kp sweep: with PWMmin {p['pwmmin']} that is what holds "
                             f"it against the load ({self.dn[-self.load['pull']]} took PWM {self.load['need']}).")
            self._apply(p)
            self._ramp_to(c)
            self._settle(c, 3.0)

        # 3. top speed each way -> how fast the test moves go
        s_now = self.board.latest()
        if s_now and s_now.get("roll") is not None:
            self.say("Motion sensor is sending: the seat's own overshoot and ringing count too" +
                     (" (how the seat turns, for the traction-loss motor)." if self.motor == tl_motor(self.board.cfg)
                      else "."))
        self._phase("speed", "Measuring top speed", 30)
        vtop = self._measure_speed(p, c, A, share)
        try:
            ts = dict(b.cfg.get("tune_speed") or {})
            ts[str(n)] = {"ramp": self.ramp_v, "top": [round(vtop[1]), round(vtop[-1])], "pwmmax": p["pwmmax"],
                          "share": round(share, 2)}
            b.cfg.update(tune_speed=ts)
        except Exception:
            pass

        # 4. Kp sweep: test moves both ways along ramps the motor can follow
        self._phase("kp", "Sweeping Kp", 33)
        kp0 = float(KP_START)
        if self.load:
            # 2.9.1: start where the P term can hold it against the load within ~60 counts: the Kps below can't
            # (the seat sits that far off, sinking while the PID pushes) and never meet the targets anyway
            need_kp = self._kp_hold(p["pwmmin"], 60.0)
            while kp0 < need_kp and kp0 * KP_STEP <= KP_MAX / 4:
                kp0 *= KP_STEP
            if kp0 > KP_START:
                self.say(f"Starting the sweep at Kp {kp0:.0f}: below that, with PWMmin {p['pwmmin']}, it can't hold "
                         f"against the load ({self.dn[-self.load['pull']]} took PWM {self.load['need']}).")
        kp_lo = int(round(kp0))            # 2.9.1: nothing below picks a Kp under the sweep's start
        p.update(ki=0, kd=0, ks=1, kp=kp_lo)
        self._apply(p)
        self._ramp_to(c)
        self._settle(c, 3.0)
        calm2 = self._calm(2.0)
        # 2.9: the hold limits - raised for the rest of the run when a restless hold turns out to be the pot's (or
        # the slide's), not the Kp's: the Kp just below is re-tested, and if it is as restless now, it wasn't the Kp
        lim = {"good": calm2, "stop": self._calm(2.5, 2.0), "pid": PID_NOISE_MAX, "raised": 0}

        def good(r):
            return (r["reached"] and r["os"] <= os_t and r["osc"] <= 2 and r["fb_std"] <= lim["good"]
                    and r["pid_std"] <= lim["pid"] and not r.get("behind"))

        def restless(r):                   # the hold is restless (the pot's spread - the PID output's buzz has its
            return r["fb_std"] > lim["stop"]   # own limit, which nothing raises: 2.9)

        def moves_calm(r):                 # ...while the moves themselves show nothing of a too-high Kp
            return (r["reached"] and not r.get("behind") and r["os"] <= max(os_t * 2, 10.0) and r["osc"] <= 2)

        def lag_ok(r):                     # both ways measured, and both within the target
            ls = [x.get("lag_ms") for x in (r.get("dp") or {}, r.get("dm") or {})]
            return None not in ls and max(ls) <= lag_t

        results, over, kp = [], 0, kp0
        best_lag, best_settle, no_gain, met, why = float("inf"), float("inf"), 0, 0, "max"
        sweep = []
        while kp <= KP_MAX:
            self.progress = 33 + int(37 * math.log(kp / kp0) / math.log(KP_MAX / kp0))
            p["kp"] = int(round(kp))
            self._apply(p)
            self._settle(c, 1.0)
            r = self._test_set(c, A, p, hold=self._hold())
            if (not good(r) and results and good(results[-1][1]) and r["reached"] and not r.get("behind")
                    and r["os"] <= OS_STOP and r["osc"] < 4 and (r["pid_std"] <= lim["pid"] or moves_calm(r))):
                # one bad test right after a calm one: a glitchy pot can kick the motor (a burst of bad readings
                # makes the PID push hard for a moment) - test this Kp once more before believing it (page 2.5)
                self.say(f"Kp {p['kp']}: {fmt(r, self.dn)} - testing it once more, to be sure.")
                self._settle(c, 1.0)
                r = self._test_set(c, A, p, hold=self._hold())
            ref = next((k for k, rr in reversed(results) if good(rr)), None)
            if restless(r) and moves_calm(r) and r["pid_std"] <= lim["pid"] and ref is not None and lim["raised"] < 3:
                # 2.9: still restless, but only while holding - no overshoot, no ringing. Before calling it the
                # Kp's fault, hold at the last calm Kp again: if that is just as restless now, it is the pot (a
                # crackling track, glitches the filter can't catch) or the slide (stick-slip), and the sweep goes on
                # with the hold limits raised to what the board does anyway
                kp_here = p["kp"]
                self.say(f"Kp {kp_here}: {fmt(r, self.dn)} - restless only while holding (no overshoot, no ringing): "
                         f"checking Kp {ref} again to see whether it's the Kp.")
                p["kp"] = ref
                self._apply(p)
                self._settle(c, 1.0)
                rr = self._test_set(c, A, p, hold=self._hold())
                p["kp"] = kp_here
                self._apply(p)
                self._settle(c, 1.0)
                if restless(rr):
                    lim["raised"] += 1
                    lim["stop"] = max(lim["stop"], 1.3 * rr["fb_std"], 1.15 * r["fb_std"])
                    lim["good"] = max(lim["good"], 1.3 * rr["fb_std"], 1.15 * r["fb_std"])
                    self.say(f"Kp {ref} is just as restless now (hold noise {rr['fb_std']:.2f}) - that's the " + ("sensor" if hall_sensor(self.board.cfg) else "pot") + f" or the "
                             f"slide, not the Kp. Carrying on, allowing for it (hold noise up to {lim['stop']:.1f}).")
                else:
                    self.say(f"Kp {ref} holds calmly again ({rr['fb_std']:.2f}) - so it is Kp {kp_here} that makes it "
                             f"restless.")
            results.append((p["kp"], r))
            if len(results) == 3:
                # 2.9: what this pot does while holding at the gentlest Kps (40-68), where the PID barely reacts -
                # a hold that restless can't be the Kp's doing later either. The limits from the noise at rest (one
                # 3 s reading, which came out 1.3 on one run and 2.7 on the next on the same rig) can be below it:
                # then every Kp looked restless and the sweep stopped while the moves were clean
                base = statistics.median(rr["fb_std"] for k, rr in results)
                if 1.5 * base > lim["stop"]:
                    lim["stop"] = max(lim["stop"], 1.5 * base)
                    lim["good"] = max(lim["good"], 1.3 * base)
                    self.say(f"This {'sensor' if hall_sensor(self.board.cfg) else 'pot'} holds at ±{base:.1f} counts even at the gentlest Kps - the hold limits allow for "
                             f"that (restless above {lim['stop']:.1f}).")
            sweep = sweep + [{"kp": p["kp"], "p": _slim(r["dp"]), "m": _slim(r["dm"]), "good": good(r)}]
            self._lv(sweep=sweep)
            self._show(f"Kp {p['kp']}", r)
            self.say(f"Kp {p['kp']}: {fmt(r, self.dn)}")
            # (a restless hold counts only once the motor got there: a slow motor still creeping in isn't lively)
            if r["os"] > OS_STOP or r["osc"] >= 4:
                self.say("Too lively - stopping the sweep here.")
                why = "edge"
                break
            if r["reached"] and r["fb_std"] > lim["stop"] and len(results) >= 3:
                self.say("Holding gets restless at this Kp - stopping the sweep here.")
                why = "edge"
                break
            if r["pid_std"] > lim["pid"]:
                self.say(f"Holding gets twitchy (the {'sensor' if hall_sensor(self.board.cfg) else 'pot'} noise is being "
                         f"amplified) - stopping the sweep here.")
                why = "edge"
                break
            if r["os"] > os_t:              # two in a row (2.4.1 counted any two, so two glitch kicks ended it)
                over += 1
                if over >= 2:
                    why = "edge"
                    break
            else:
                over = 0
            if good(r) and lag_ok(r):
                met += 1
                if met >= 2:
                    why = "enough"
                    self.say(f"Follows within {lag_t:.0f} ms both ways - no need to go stiffer.")
                    break
            else:
                met = 0
            if good(r) and r["settled"]:          # "no better" only counts among calm tests
                lm = r["lag_ms"] if r.get("lag_ms") is not None else float("inf")
                if lm < best_lag * 0.9 or r["settle"] < best_settle * 0.95:
                    no_gain = 0
                else:
                    no_gain += 1
                best_lag, best_settle = min(best_lag, lm), min(best_settle, r["settle"])
                if no_gain >= 3:
                    why = "nogain"
                    self.say("Higher Kp isn't improving anything any more - stopping the sweep.")
                    break
            kp *= KP_STEP
        goods = [(k, r) for k, r in results if good(r)]
        notes = []
        if goods:
            tight = min(r["sse"] for k, r in goods)
            sse_ok = max(tight * 1.5, p["dz"] + 3.0)
            cap = max(kp_lo, int(round(goods[-1][0] * margin)))
            meet = next(((k, r) for k, r in goods if lag_ok(r) and r["settled"] and r["sse"] <= sse_ok), None)
            if meet and (why != "edge" or meet[0] <= cap):
                kp_best, r_best = meet
                self.say(f"Kp {kp_best} follows the test moves within {r_best['lag_ms']:.0f} ms both ways "
                         f"(target {lag_t:.0f}) - higher only adds harshness.")
            elif meet or why == "edge":
                kp_best, r_best = goods[-1][0] * margin, goods[-1][1]
                self.say(f"Highest calm Kp {goods[-1][0]} -> using {int(margin * 100)}% of it for a safety margin"
                         + (f" (it follows {r_best['lag_ms']:.0f} ms behind; the target was {lag_t:.0f})."
                            if r_best.get("lag_ms") is not None and not lag_ok(r_best) else "."))
            else:
                best_l = min((r["lag_ms"] for k, r in goods if r.get("lag_ms") is not None), default=None)
                knee = None
                if best_l is not None:
                    knee = next(((k, r) for k, r in goods if r.get("lag_ms") is not None and r["settled"]
                                 and r["lag_ms"] <= best_l * knee_tol + 5 and r["sse"] <= sse_ok), None)
                if knee:
                    kp_best, r_best = knee
                    self.say(f"Sweet spot: Kp {kp_best} - higher values didn't follow noticeably better.")
                else:
                    kp_best, r_best = goods[-1][0] * margin, goods[-1][1]
                    self.say(f"Highest calm Kp {goods[-1][0]} -> using {int(margin * 100)}% of it for a safety "
                             f"margin.")
        else:
            reached = [(k, r) for k, r in results if r["reached"]]
            if not reached and why == "edge":
                k, r = results[-1]
                raise TuneAbort(f"motor {n} is too lively even at Kp {k} (overshoot {r['os']:.0f}%, ringing "
                                f"{r['osc']}) before it even gets there. Check for slack between motor and pot, and for "
                                f"a glitchy pot (the Diagnostics quick check counts glitches).")
            if not reached:
                raise TuneAbort(f"motor {n} never reached the target within 2 s, even at Kp {results[-1][0]}. "
                                f"PWMmax {p['pwmmax']} is probably too low for this load.")
            kp_best, r_best = reached[0]
            why_not = []
            if r_best["os"] > os_t:
                why_not.append(f"overshoots {r_best['os']:.0f}% (check for slack between motor and pot)")
            if r_best["osc"] > 2:
                why_not.append(f"swings {r_best['osc']}x before it settles")
            if r_best.get("behind"):
                why_not.append("can't keep up with the test moves (PWMmax too low for the load?)")
            if r_best["fb_std"] > lim["good"]:
                why_not.append(f"doesn't hold still (±{r_best['fb_std']:.1f} counts - a noisy or glitchy pot?)")
            if r_best["pid_std"] > lim["pid"]:
                why_not.append("buzzes while holding (pot noise amplified)")
            notes.append(f"No Kp was calm: even the gentlest one that gets there (Kp {kp_best}) "
                         + ("; ".join(why_not) or "falls outside the limits") + ". It is used as it is.")
        # floor: whatever the style, don't settle on a Kp that leaves the seat far from where it is sent
        calm_enough = [(k, r) for k, r in results if r["reached"] and r["os"] <= max(os_t, 15.0) and r["osc"] <= 2
                       and r["pid_std"] <= lim["pid"] and r["fb_std"] <= lim["good"] and not r.get("behind")]
        limit = (goods[-1][0] * margin) if (goods and why == "edge") else float("inf")
        floor = next((k for k, r in calm_enough if r["sse"] <= SSE_FLOOR and k <= limit), None)
        if floor is not None and kp_best < floor:
            self.say(f"Kp {int(kp_best)} would leave the seat more than {SSE_FLOOR:.0f} counts short - using Kp "
                     f"{floor}, the lowest that gets there.")
            kp_best = floor
        p["kp"] = max(kp_lo, int(round(kp_best)))
        self._lv(chosen=p["kp"])
        self.say(f"Kp {p['kp']}.")
        # 5. small movements (road-texture sized, sharp like a kerb) must not ring
        self._phase("small", "Checking small movements", 72)
        self._apply(p)
        prev = None                        # (Kp, why, hold noise) before the last cut
        for _ in range(3):
            self._ramp_to(c)
            self._settle(c, 2.0)
            rs = self._test_set(c, SMALL_STEP, p, hold=1.3, ramp=False)
            self._show(f"Small ±{SMALL_STEP} steps, Kp {p['kp']}", rs, "small")
            self.say(f"Small ±{SMALL_STEP} steps at Kp {p['kp']}: {fmt(rs, self.dn)}")
            ringing = rs["osc"] >= 2 or rs["os"] > 35
            # 2.9: the sweep's hold limit (it was a stricter 1.5 x the noise at rest, which cut a clean Kp 103 to 52
            # on a real rig, 20% at a time, while the hold stayed as it was: 2.22, 2.07, 2.41)
            restless = rs["fb_std"] > lim["stop"]
            if prev and prev[1] == "hold" and not ringing and rs["fb_std"] > 0.85 * prev[2]:
                p["kp"] = prev[0]
                self._apply(p)
                self._lv(chosen=p["kp"])
                self.say(f"Lowering Kp didn't make the hold calmer ({prev[2]:.2f} -> {rs['fb_std']:.2f}) - that's the "
                         f"pot, not the Kp: back to Kp {p['kp']}.")
                break
            if (ringing or restless) and p["kp"] > kp_lo:
                prev = (p["kp"], "ring" if ringing else "hold", rs["fb_std"])
                p["kp"] = max(kp_lo, int(p["kp"] * 0.8))
                self._apply(p)
                self._lv(chosen=p["kp"])
                self.say(("Small moves ring" if ringing else "Small moves hold restlessly") +
                         f" - Kp reduced to {p['kp']}.")
            else:
                break

        # 6. Ki, if the motor settles short of the target (big or small moves) - or, allowing for a rider, a little
        #    anyway: the rider's weight leaves the lifts short going up
        self._phase("ki", "Checking steady-state error (Ki)", 76)

        def measure(label):
            self._ramp_to(c)
            self._settle(c, 2.0)
            big = self._test_set(c, A, p, hold=2.0)
            self._show(label + ", test moves", big)
            self._settle(c, 1.0)
            small = self._test_set(c, SMALL_STEP, p, hold=1.3, ramp=False)
            self._show(label + ", small steps", small, "small")
            return big, small

        r_base, r_small = measure(f"Kp {p['kp']}")
        self.say(f"Kp {p['kp']}, test moves: {fmt(r_base, self.dn)}")
        self.say(f"Kp {p['kp']}, small steps: {fmt(r_small, self.dn)}")
        tol = p["dz"] + 1.5
        sse0 = max(r_base["sse"], r_small["sse"])
        need = sse0 > tol
        for_rider = fr > 0 and not need
        if do_ki and (need or for_rider):
            best = None
            tried = []                     # (ki, big, small) of every calm step (page 2.6)
            steps = KI_STEPS if need else KI_STEPS[:2]
            for i, ki in enumerate(steps):
                self.progress = 77 + 2 * i
                p["ki"] = ki
                self._apply(p)
                big, small = measure(f"Ki {ki}")
                self.say(f"Ki {ki}: test moves {big['os']:.0f}% over / off by {big['sse']:.1f}, "
                         f"small {small['os']:.0f}% over / off by {small['sse']:.1f}")
                # judged against what was already there, so a springy linkage's normal ringing doesn't veto it;
                # ringing on the motor only - holding position (Ki) isn't what makes a flexing frame ring
                mo = lambda r: r.get("motor_osc", r["osc"])
                too_much = lambda bg, sm: (bg["os"] > r_base["os"] + 8 or mo(bg) > max(2, mo(r_base) + 1)
                                           or mo(sm) > max(2, mo(r_small) + 1) or sm["os"] > max(35.0, r_small["os"] + 15))
                if too_much(big, small):
                    if i == 0 and ki > KI_SMALL and need:
                        # 2.9: the first step is already too much - a smaller one may still take the error down
                        # (a rear slide that stops short one way: Ki 5 halved it on a real rig, at 9% overshoot)
                        self.say(f"Ki {ki} overshoots ({big['os']:.0f}%) - trying Ki {KI_SMALL}.")
                        p["ki"] = KI_SMALL
                        self._apply(p)
                        big2, small2 = measure(f"Ki {KI_SMALL}")
                        self.say(f"Ki {KI_SMALL}: test moves {big2['os']:.0f}% over / off by {big2['sse']:.1f}, "
                                 f"small {small2['os']:.0f}% over / off by {small2['sse']:.1f}")
                        if not too_much(big2, small2):
                            best = (KI_SMALL, big2, small2)
                            tried.append(best)
                            break
                    self.say("Ki starts causing overshoot - stopping.")
                    break
                best = (ki, big, small)
                tried.append(best)
                if need and max(big["sse"], small["sse"]) <= tol:
                    break
                # 2.6: stop once a step of Ki no longer brings the error down by a count - it's at the floor the
                # dead zone and the pot noise set, and more Ki only adds overshoot
                if need and len(tried) >= 2:
                    e1, e2 = (max(x[1]["sse"], x[2]["sse"]) for x in tried[-2:])
                    if e1 - e2 < max(1.0, 0.15 * e1):
                        self.say(f"Ki {ki} hardly helps any more ({e1:.1f} -> {e2:.1f} counts) - stopping.")
                        break
            if need and tried:
                # the smallest Ki within a count (or 15%) of the best leftover error: (2.5 kept the last one tried,
                # which on a real rig went up to Ki 70 for 2 counts less error and 25 points more overshoot)
                e_min = min(max(x[1]["sse"], x[2]["sse"]) for x in tried)
                best = next(x for x in tried if max(x[1]["sse"], x[2]["sse"]) <= e_min + max(1.0, 0.15 * e_min))
            if need and best and max(best[1]["sse"], best[2]["sse"]) < sse0 * 0.7:
                p["ki"], r_base, r_small = best
            elif for_rider and best:
                p["ki"], r_base, r_small = best
                self.say(f"Ki {p['ki']} kept for the rider: the empty seat settles within {sse0:.1f} counts, but your "
                         f"weight leaves the motor short (most going up) and Ki makes that up.")
            else:
                p["ki"] = 0
            self.say(f"Ki {p['ki']}.")
        elif do_ki:
            p["ki"] = 0
            self.say(f"Settles within {sse0:.1f} counts on test moves and small steps - Ki not needed (0).")
        self._apply(p)

        # 7. Kd, only if there is overshoot to damp and it helps without adding noise
        self._phase("kd", "Trying damping (Kd)", 88)
        if do_kd and r_base["os"] > 2:
            def score(r):
                return r["os"] + r["settle"] / 40.0
            self._ramp_to(c)
            self._settle(c, 2.0)
            best = None
            for i, kd in enumerate(KD_STEPS):
                self.progress = 88 + 2 * i
                p.update(ks=4, kd=kd)
                self._apply(p)
                self._settle(c, 1.0)
                r = self._test_set(c, A, p, hold=self._hold())
                self._show(f"Kd {kd}", r)
                self.say(f"Kd {kd} (Ks 4): {fmt(r, self.dn)}")
                if r["pid_std"] > r_base["pid_std"] * 1.5 + 3 or r["fb_std"] > lim["good"] or r["osc"] >= 2:
                    self.say("Kd starts adding noise - stopping.")
                    break
                if best is None or score(r) < score(best[1]):
                    best = (kd, r)
            if best and score(best[1]) <= 0.85 * score(r_base):
                p.update(kd=best[0], ks=4)
                self.say(f"Kd {best[0]} with Ks 4 helps.")
            else:
                p.update(kd=0, ks=1)
                self.say("Kd doesn't help enough - keeping it at 0.")
            self._apply(p)
        elif do_kd:
            p.update(kd=0, ks=1)
            self._apply(p)
            self.say("Hardly any overshoot - Kd not needed (0).")

        # 8. verify and finish at centre
        self._phase("final", "Verifying", 97)
        r_final, r_fsmall = measure("Final")
        self.say(f"Final, test moves: {fmt(r_final, self.dn)}")
        self.say(f"Final, small steps: {fmt(r_fsmall, self.dn)}")
        self._show("Final, test moves", r_final)
        self._ramp_to(c)
        self._settle(c, 3.0)
        keys = ["kp", "ki", "kd", "ks", "pwmmin", "dz"]
        nz = self.live.get("noise") or {}
        if nz.get("capped") and do_friction:         # 2.9.2: say it in the result too, not only in the log
            notes.append(f"The {'sensor' if hall_sensor(b.cfg) else 'pot'} noise at rest (±{nz['sd']:.2f} counts) "
                         f"would need a dead zone of {nz['dz_wanted']}; it is capped at 4, so the motor may tick or "
                         f"hunt while holding. Fix the signal (Diagnostics, Sensor check A / B / C), then tune again.")
        if r_final.get("seat_os") is not None:
            if r_final["seat_os"] >= 25 and r_final["seat_os"] >= r_final.get("motor_os", 0) + 20:
                notes.append(f"The seat itself still bounces ({r_final['seat_os']:.0f}% overshoot) after the motor "
                             f"stops - the frame, seat mounts or linkage flex. More target smoothing softens it; "
                             f"stiffening the frame fixes it.")
        # drive headroom: what following the test moves takes, each way, with the final values
        drv = {d: (r_final["dp"] if d > 0 else r_final["dm"]).get("drive") for d in (1, -1)}
        hard = max((d for d in (1, -1) if drv[d] is not None), key=lambda d: drv[d], default=None)
        if hard is not None:
            pct = 100.0 * drv[hard] / max(1, p["pwmmax"])
            sat = (r_final["dp"] if hard > 0 else r_final["dm"]).get("sat") or 0.0
            if r_final.get("behind") or pct >= 92 or sat > 0.3:
                notes.append(f"Following the test moves ({self.ramp_v} counts/s) takes all of PWMmax "
                             f"({p['pwmmax']}) going {self.dn[hard]} - big fast moves will lag that way. Raise PWMmax "
                             f"by 10-20 and run auto-tune again.")
            elif fr > 0 and pct > 70:
                sug = int(min(255, max(p["pwmmax"] + 10, math.ceil(drv[hard] / 0.6 / 5.0) * 5)))
                notes.append(f"With the seat empty, following the test moves already takes {pct:.0f}% of PWMmax "
                             f"going {self.dn[hard]}. With {kg_text(rider_kg, unit)} in it that way needs more - "
                             f"consider PWMmax {sug} (now {p['pwmmax']}), then run Check with you in the seat.")
        if fr > 0:
            notes.append(f"Tuned with the seat empty, allowing for {kg_text(rider_kg, unit)}. Sit in it and press "
                         f"Check: it tests these values with you in the seat (about 30 s) and says what to change.")
        self.result = {"motor": n, "before": {k: orig[k] for k in keys}, "after": {k: p[k] for k in keys},
                       "final": _slim(r_final), "dirs": {"p": _slim(r_final["dp"]), "m": _slim(r_final["dm"])},
                       "small": {"p": _slim(r_fsmall["dp"]), "m": _slim(r_fsmall["dm"])},
                       "names": {"p": self.dn[1], "m": self.dn[-1]}, "ramp_v": self.ramp_v, "pwmmax": p["pwmmax"],
                       "notes": notes, "noise": self.live.get("noise")}     # 2.9.2: the noise, and whether it capped dz
        for note in notes:
            self.say("Note: " + note)
        self.say("Done. The new values are running now but NOT saved - try them in a game, then press "
                 "'Save to EEPROM' to keep them or 'Revert' to go back.")
        self.progress = 100

    # ---- 2.9: every motor together ----
    def _jset(self, m, v):
        v = int(max(self.jwin[m][0], min(self.jwin[m][1], round(v))))
        self.board.cmd_word("ABC"[m], 1023 - v if (m == 0 and self.jrev) else v)
        if v != self.jstart.get(m, v):
            self.moved = True
        self.jcur[m] = v
        self.last_cmd = time.time()
        self.jrecent[m].append((self.last_cmd, v))

    def _jramp(self, xs, v):
        """Every motor in xs from where it is to its target at once, on the same eased profile (the longest move at
        v counts/s, the others in step with it), 50 updates a second."""
        x0 = {m: float(self.jcur[m]) for m in xs}
        far = max(abs(xs[m] - x0[m]) for m in xs)
        if far < 1.0 or v <= 0:
            for m in xs:
                self._jset(m, xs[m])
            return
        a = v / 0.12
        ta = v / a
        if a * ta * ta >= far:
            ta, tc, vp = math.sqrt(far / a), 0.0, None
            vp = a * ta
        else:
            tc, vp = (far - a * ta * ta) / v, v
        total = 2 * ta + tc
        t_start = time.time()
        while True:
            t = time.time() - t_start
            if t >= total:
                break
            if t < ta:
                sd = 0.5 * a * t * t
            elif t < ta + tc:
                sd = 0.5 * a * ta * ta + vp * (t - ta)
            else:
                td = total - t
                sd = far - 0.5 * a * td * td
            f = sd / far
            for m in xs:
                self._jset(m, x0[m] + (xs[m] - x0[m]) * f)
            self._check()
            time.sleep(0.02)
        for m in xs:
            self._jset(m, xs[m])

    def _jfb(self, m, n=9):
        with self.board.slock:
            snap = list(self.board.samples)[-n:]
        fs = [x["m"][m]["f"] for x in snap]
        return statistics.median(fs) if fs else 512.0

    def _jsettle(self, xs, timeout):
        end = time.time() + timeout
        while time.time() < end:
            self.wait(0.1)
            if all(abs(self._jfb(m, 5) - xs[m]) <= max(4.0, 1.5 * self.jnoise.get(m, 0.5)) for m in xs):
                self.wait(0.2)
                return True
        return False

    def _jcheck(self):
        if self.abort_flag:
            raise TuneAbort("Stopped by you.")
        if not self.board.connected:
            raise TuneAbort("Lost the connection to the board.")
        if self.board.conn_id != getattr(self, "conn0", self.board.conn_id):
            raise TuneAbort("The connection to the board changed during the run (the USB bridge closed, or the "
                            "board restarted).")
        new = self.board.since(self.chk_seq)
        if not new:
            return
        self.chk_seq = new[-1]["seq"]
        now = time.time()
        for m in self.jm:
            n = m + 1
            allowed = {v for t, v in self.jrecent[m] if now - t < 15.0} | {self.jcur[m]}
            lo_ok, hi_ok = self.jwin[m][0] - 25, self.jwin[m][1] + 25
            for smp in new:
                mm = smp["m"][m]
                self.jfwin[m].append(mm["f"])
                fmed = statistics.median(self.jfwin[m])
                if smp["dis"][m]:
                    raise TuneAbort(f"Motor {n} was shut off by its safety cutoff (feedback went past Max limit).",
                                    "unsafe")
                if mm["t"] in allowed:
                    self.jinterf[m] = 0
                else:
                    self.jinterf[m] += 1
                    if self.jinterf[m] >= 6:
                        raise TuneAbort(f"Something else is moving motor {n} (SimHub?). Stop SimHub's motion output "
                                        f"and start again.")
                if abs(mm["t"] - fmed) > self.runaway_limit:
                    raise TuneAbort(f"Motor {n} ran away from its target - most likely the motor or the pot is wired "
                                    f"backwards (or the pot slipped on its shaft).", "unsafe")
                if fmed < lo_ok or fmed > hi_ok:
                    raise TuneAbort(f"Motor {n} went outside its allowed travel ({fmed:.0f}).")

    def _jstop(self, unsafe):
        """End of a joint run that didn't finish: every motor holds where it is - switched off first if unsafe."""
        if unsafe and self.board.fwnum() >= 15:
            for m in self.jm:
                self.board.cmd_text(f"di{m + 1}")
                time.sleep(0.05)
            self.say("SAFETY: the motors are switched off; their values are unchanged. Fix the cause first, then "
                     "press Enable Motors.")
        if self.moved:
            for m in self.jm:
                try:
                    self._jset(m, self._jfb(m))
                except Exception:
                    pass

    def _jmove_once(self, xs, hold, ps, t_old):
        seq0 = self.board.seq
        t_begin = time.time()
        t0 = time.time()
        self._jramp(xs, self.ramp_v)
        page_ms = (time.time() - t0) * 1000.0
        self.wait(hold)
        self.wait(0.15)
        out = {}
        keep = self.motor
        try:
            for m in xs:
                got = despike(self.board.since(seq0 - 30), m)
                self.motor = m                                   # (_link_trouble reads this motor's figures)
                why = self._link_trouble(got, seq0, t_old[m], xs[m], page_ms if page_ms > 150 else None,
                                         (time.time() - t_begin) * 1000.0)
                if why:
                    return None, f"motor {m + 1}: {why}"
                r = analyze_move(got, m, t_old[m], ps[m]["pwmmin"], ps[m]["pwmmax"], hold * 1000 - 100,
                                 self.jnoise[m], seq0)
                if r is None:
                    return None, f"motor {m + 1}'s move didn't show up in the telemetry"
                if r["wrong"]:
                    raise TuneAbort(f"Motor {m + 1} moved the wrong way. The motor or the pot is wired backwards.",
                                    "unsafe")
                out[m] = r
        finally:
            self.motor = keep
        return out, None

    def _jmove(self, xs, hold, ps):
        """One move of several motors at once; a move the link spoiled goes back and is done again (as _move)."""
        t_old = {m: self.jcur[m] for m in xs}
        for attempt in range(4):
            r, why = self._jmove_once(xs, hold, ps, t_old)
            if not why:
                return r
            if attempt == 3:
                raise TuneAbort(f"The link to the board kept stalling during the test moves ({why}).")
            self.link_trouble_at = time.time()
            self.say(f"Link hiccup during that move ({why}) - doing it again.")
            self._jramp(t_old, self.ramp_v)
            self.wait(1.0)
            self._jsettle(t_old, 3.0)

    def _jset_test(self, signs, c, A, ps, hold=1.6):
        """Out and back each way, as _test_set, for every motor in signs at once: sign +1 sets off towards higher
        counts. Returns {motor: result with 'dp' / 'dm'}."""
        moves = []
        for f in (1, 0, -1, 0):
            moves.append(self._jmove({m: c[m] + signs[m] * f * A for m in signs}, hold, ps))
        res = {}
        for m, sg in signs.items():
            up = (moves[0][m], moves[3][m]) if sg > 0 else (moves[1][m], moves[2][m])
            dn = (moves[1][m], moves[2][m]) if sg > 0 else (moves[0][m], moves[3][m])
            dp, dm = worst(*up), worst(*dn)
            r = worst(dp, dm)
            r["dp"], r["dm"] = dp, dm
            res[m] = r
        return res

    def _run_joint(self, motor, amp, style, do_friction, do_ki, do_kd, rider="empty", rider_kg=0.0, unit="lb"):
        """Every motor in use with its CURRENT values (page 2.9): each one alone, then all together (the lifts up
        and down at once), then twisted (the front lifts opposite each other). Changes nothing; says where moving
        together costs a motor something - the motors share one power supply and one frame."""
        b = self.board
        cfg = b.cfg
        jm = self.jm
        names_all = {}
        self._lv(phases=[[k, l] for k, l in JOINT_PHASES], joint=True, jm=[m + 1 for m in jm], style=style)
        self._phase("prep", "Reading settings", 2)
        self.say(f"Test of motors {', '.join(str(m + 1) for m in jm)} together, with their current values, travel "
                 f"±{amp} counts. Nothing is changed.")
        pr = b.read_params()
        fw = pr.get("FW")
        if not fw or fw[1] < 14:
            raise TuneAbort("the test needs firmware 1.4 or newer on the board.", "refuse")
        self.jrev = bool(fw[0] & 1)
        s0 = b.latest()
        if not s0:
            raise TuneAbort("No telemetry from the board yet.", "refuse")
        ps, c = {}, {}
        self.jwin, self.jcur, self.jstart, self.jrecent = {}, {}, {}, {}
        self.jfwin, self.jinterf, self.jnoise = {}, {}, {}
        room = []
        for m in jm:
            n = m + 1
            need = [f"Kp{n}", f"Ki{n}", f"Kd{n}", f"Ks{n}", f"PWM{n}", f"DZ{n}"]
            if any(k not in pr for k in need):
                raise TuneAbort(f"Couldn't read motor {n}'s settings from the board. Try again.", "refuse")
            if s0["dis"][m]:
                raise TuneAbort(f"motor {n} is shut off - press 'Enable motors' first.", "refuse")
            ps[m] = {"kp": pr[f"Kp{n}"], "ki": pr[f"Ki{n}"], "kd": pr[f"Kd{n}"], "ks": pr[f"Ks{n}"],
                     "pwmmin": pr[f"PWM{n}"][0], "pwmmax": pr[f"PWM{n}"][1], "dz": pr[f"DZ{n}"][0]}
            self.jwin[m] = b.window(m)
            c[m] = b.centre(m)
            room.append(min(c[m] - self.jwin[m][0], self.jwin[m][1] - c[m]) - 60)
            self.jcur[m] = s0["m"][m]["t"]
            self.jstart[m] = self.jcur[m]
            self.jrecent[m] = collections.deque(maxlen=1500)
            self.jrecent[m].append((time.time(), self.jcur[m]))
            self.jfwin[m] = collections.deque(maxlen=5)
            self.jinterf[m] = 0
            names_all[m] = dict(self._directions(m))
            self.say(f"Motor {n}: Kp {ps[m]['kp']}, Ki {ps[m]['ki']}, Kd {ps[m]['kd']}, PWMmin {ps[m]['pwmmin']}, "
                     f"PWMmax {ps[m]['pwmmax']}, dead zone {ps[m]['dz']}.")
        if min(room) < 40:
            raise TuneAbort("the allowed travel of one of the motors is too narrow to test in.", "refuse")
        A = int(max(40, min(amp, min(room))))
        if A < amp:
            self.say(f"Travel limited to ±{A} by the allowed travel.")
        self.runaway_limit = 2 * A + 80
        self.moved, self.chk_seq, self.t_start = False, b.seq, time.time()
        self._lv(travel=A)
        # test speed: the slowest motor's, from its last auto-tune (so every motor can follow)
        vs = []
        for m in jm:
            ts = (cfg.get("tune_speed") or {}).get(str(m + 1)) or {}
            if ts.get("ramp") and ts.get("pwmmax") == ps[m]["pwmmax"]:
                vs.append(int(ts["ramp"]))
        self.ramp_v = min(vs) if vs else 200
        self.say(f"Test moves at {self.ramp_v} counts/s" + (" - the slowest motor's speed from its last auto-tune."
                 if vs else " (no auto-tune speed known yet)."))
        self._lv(speed={"ramp": self.ramp_v})
        self._phase("prep", "Moving to centre", 5)
        self._jramp(c, 160.0)
        self._jsettle(c, 5.0)
        for m in jm:
            if abs(self._jfb(m) - c[m]) > 40:
                raise TuneAbort(f"motor {m + 1} didn't follow the target (feedback {self._jfb(m):.0f}, wanted "
                                f"{c[m]}). Is motor power on?")
        # pot noise of each, at rest
        self._phase("noise", "Measuring pot noise", 10)
        self.wait(1.0)
        seq = b.seq
        self.wait(1.5)
        got = b.since(seq)
        for m in jm:
            fs = [x["m"][m]["f"] for x in got]
            resid = [fs[i] - _mean(fs[i - 2:i + 3]) for i in range(2, len(fs) - 2)]
            self.jnoise[m] = max(0.3, _rstd(resid) * 1.12) if resid else 0.5
        self.say("Pot noise at rest: " + ", ".join(f"motor {m + 1} ±{self.jnoise[m]:.2f}" for m in jm) + ".")
        self._lv(jnames={str(m + 1): {"p": names_all[m][1], "m": names_all[m][-1]} for m in jm})
        lifts, tl = [m for m in lift_motors(cfg) if m in jm], tl_motor(cfg)
        fw_ = lambda m: -1 if names_all[m].get(-1) in ("up", "right") else 1      # up first, right first
        rows = {m: {} for m in jm}

        def show(key, res):
            for m, r in res.items():
                rows[m][key] = {"p": _slim(r["dp"]), "m": _slim(r["dm"]), "fb_std": round(r["fb_std"], 2),
                                "pid_std": round(r["pid_std"], 2)}
            self._lv(jrows={str(m + 1): dict(rows[m]) for m in jm}, n=self.live.get("n", 0) + 1)

        # 1. each alone - its own figures to compare with
        self._phase("solo", "Each motor alone", 15)
        for i, m in enumerate(jm):
            self.progress = 15 + int(35 * i / len(jm))
            self._jsettle(c, 2.0)
            r = self._jset_test({m: fw_(m)}, c, A, ps)
            show("solo", r)
            self.say(f"Motor {m + 1} alone: {fmt(r[m], names_all[m])}")
        # 2. together: the lifts up at once (and the rear slide with them)
        self._phase("together", "All together", 55)
        self._jsettle(c, 2.0)
        sg = {m: fw_(m) for m in jm}
        rt = self._jset_test(sg, c, A, ps)
        show("together", rt)
        for m in jm:
            self.say(f"Motor {m + 1}, all together: {fmt(rt[m], names_all[m])}")
        # 3. twisted: the first two lifts opposite each other
        ro = None
        if len(lifts) >= 2:
            self._phase("opposite", "Twisted", 75)
            self._jsettle(c, 2.0)
            so = dict(sg)
            so[lifts[1]] = -so[lifts[1]]
            ro = self._jset_test(so, c, A, ps)
            show("opposite", ro)
            for m in jm:
                self.say(f"Motor {m + 1}, twisted: {fmt(ro[m], names_all[m])}")
        self._phase("end", "Back to where they were", 95)
        self._jramp(self.jstart, 160.0)
        self._jsettle(self.jstart, 3.0)
        # verdict: what moving together costs each motor, each way - one line per motor
        issues, suggest, power, frame = [], [], False, False
        for m in jm:
            nm, found = names_all[m], []
            for key, label in (("together", "together"), ("opposite", "twisted")):
                if key not in rows[m]:
                    continue
                res = rt if key == "together" else ro
                for d, k, rk in ((1, "dp", "p"), (-1, "dm", "m")):
                    a, z = rows[m]["solo"][rk], res[m][k]
                    w = f"{nm[d]} {label}"
                    if a.get("lag_ms") is not None and z.get("lag_ms") is not None and \
                            z["lag_ms"] > 1.25 * a["lag_ms"] and z["lag_ms"] - a["lag_ms"] > 25:
                        out = (z.get("behind") or (z.get("sat") or 0) > 0.3) and not (a.get("behind") or
                                                                                      (a.get("sat") or 0) > 0.3)
                        found.append(f"lags {z['lag_ms']:.0f} ms going {w} (alone {a['lag_ms']:.0f})" +
                                     (", out of drive" if out else ""))
                        power = True
                    elif (z.get("behind") or (z.get("sat") or 0) > 0.3) and not (a.get("behind") or
                                                                                 (a.get("sat") or 0) > 0.3):
                        found.append(f"runs out of drive going {w}")
                        power = True
                    if z["os"] > a["os"] + 8 and z["os"] > 10:
                        found.append(f"overshoots {z['os']:.0f}% going {w} (alone {a['os']:.0f}%)")
                        frame = True
                    if z["osc"] > max(2, a["osc"] + 1):
                        found.append(f"rings going {w}")
                        frame = True
                    if z["sse"] > a["sse"] + 3 and z["sse"] > ps[m]["dz"] + 3:
                        found.append(f"stops {z['sse']:.1f} counts short going {w} (alone {a['sse']:.1f})")
            if found:
                issues.append(f"motor {m + 1} " + ", ".join(found))
        if power:
            suggest.append("The motors share the power supply: when they all pull at once it may sag. Check its "
                           "current rating against the motors' stall current, the voltage at the motor drivers while "
                           "they all move, and the wire gauge - or lower PWMmax a little on every motor.")
        if frame:
            suggest.append("Overshoot or ringing that shows only together comes from the frame or the seat flexing "
                           "when the motors work against each other: stiffen the mounts, or let auto-tune try Kd.")
        ok = not issues
        self.say("Together: " + ("every motor does as well as alone." if ok else "; ".join(issues) + "."))
        self.result = {"joint": True, "ok": ok, "issues": issues, "suggest": suggest, "amp": A,
                       "ramp_v": self.ramp_v, "motors": [m + 1 for m in jm],
                       "names": {str(m + 1): {"p": names_all[m][1], "m": names_all[m][-1]} for m in jm},
                       "rows": {str(m + 1): rows[m] for m in jm},
                       "values": {str(m + 1): ps[m] for m in jm}}
        self.progress = 100

    def _run_check(self, m, amp, style, do_friction, do_ki, do_kd, rider="empty", rider_kg=0.0, unit="lb"):
        """Check (page 2.5): the motor's CURRENT values on test moves both ways and small steps - typically with you
        in the seat after tuning it empty. Changes nothing; says what to change."""
        b, n = self.board, m + 1
        os_t, _, _, lag_t = STYLES.get(style, STYLES["normal"])
        seated = rider == "seated"
        self._lv(phases=[[k, l] for k, l in CHECK_PHASES if k != "countdown" or seated], style=style,
                 rider={"mode": "seated" if seated else "empty", "kg": rider_kg, "unit": unit}, check=True)
        self.say(f"Check of motor {n}'s current values, style '{style}', travel ±{amp} counts"
                 + (" - you in the seat." if seated else " - seat empty."))
        p, c, lo, hi, A = self._prepare(m, amp, check=True)
        self.say(f"Values: Kp {p['kp']}, Ki {p['ki']}, Kd {p['kd']} (Ks {p['ks']}), PWMmin {p['pwmmin']}, PWMmax "
                 f"{p['pwmmax']}, dead zone {p['dz']}. Nothing is changed.")
        tol = p["dz"] + 3.0
        self._lv(targets={"lag_ms": round(lag_t), "os": round(os_t, 1), "settle": SETTLE_OK_MS, "sse": tol,
                          "pid": PID_NOISE_MAX})
        if seated:
            self._countdown(COUNTDOWN_S)
        self._phase("prep", "Moving to centre", 5)
        self._ramp_to(c)
        self._settle(c, 4.0, tol=max(4.0, p["dz"] + 2))
        if abs(self._fb_med() - c) > 40:
            raise TuneAbort(f"motor {n} didn't follow the target (feedback {self._fb_med():.0f}, wanted {c}). "
                            f"Is motor power on?")
        self._noise(m, False, p)
        self._phase("speed", "Test speed", 15)
        ts = (b.cfg.get("tune_speed") or {}).get(str(n)) or {}
        if ts.get("ramp") and ts.get("pwmmax") == p["pwmmax"]:
            self.ramp_v = int(ts["ramp"])
            self._lv(speed={"p": (ts.get("top") or [None, None])[0], "m": (ts.get("top") or [None, None])[1],
                            "ramp": self.ramp_v, "share": round(100 * (ts.get("share") or RAMP_SHARE)),
                            "pwmmax": p["pwmmax"]})
            self.say(f"Test moves at {self.ramp_v} counts/s, as in the last auto-tune of this motor.")
        else:
            self._measure_speed(p, c, A, RAMP_SHARE, change=False)
        self._phase("big", "Test moves", 40)
        self._ramp_to(c)
        self._settle(c, 3.0)
        big = self._test_set(c, A, p, hold=2.0)
        self._show("Test moves", big)
        self.say(f"Test moves: {fmt(big, self.dn)}")
        self._phase("small", "Small steps", 75)
        self._settle(c, 2.0)
        small = self._test_set(c, SMALL_STEP, p, hold=1.3, ramp=False)
        self._show(f"Small ±{SMALL_STEP} steps", small, "small")
        self.say(f"Small ±{SMALL_STEP} steps: {fmt(small, self.dn)}")
        self._ramp_to(c)
        self._settle(c, 2.0)
        # verdict, each way
        issues, suggest = [], []
        by = {1: big["dp"], -1: big["dm"]}
        sm = {1: small["dp"], -1: small["dm"]}
        slow = [d for d in (1, -1) if by[d].get("lag_ms") is not None and by[d]["lag_ms"] > 1.1 * lag_t]
        over = [d for d in (1, -1) if by[d]["os"] > os_t or sm[d]["os"] > 35]
        ring = [d for d in (1, -1) if by[d]["osc"] > 2 or sm[d]["osc"] >= 2]      # as auto-tune judges them
        miss = [d for d in (1, -1) if not by[d]["reached"]]
        short = [d for d in (1, -1) if max(by[d]["sse"], sm[d]["sse"]) > tol]
        flat = [d for d in (1, -1) if by[d].get("behind") or (by[d].get("drive") or 0) >= 0.92 * p["pwmmax"]
                or (by[d].get("sat") or 0) > 0.3]
        names = lambda ds: " and ".join(self.dn[d] for d in ds)
        if slow:
            w = max(by[d]["lag_ms"] for d in slow)
            issues.append(f"follows {w:.0f} ms behind going {names(slow)} (target {lag_t:.0f})")
            if not over and not ring:
                sug = int(round(min(p["kp"] * 1.6, max(p["kp"] * 1.15, p["kp"] * w / lag_t)) / 5.0) * 5)
                suggest.append(f"Raise Kp to about {sug} (now {p['kp']}) - or run auto-tune with you in the seat.")
        if over:
            w = max(max(by[d]["os"], sm[d]["os"]) for d in over)
            issues.append(f"overshoots {w:.0f}% going {names(over)} (limit {os_t:.0f}%)")
            suggest.append("Lower Kp by about 20%, or let auto-tune try Kd (damping) with you in the seat.")
        if ring:
            issues.append(f"rings going {names(ring)}")
            if not over:
                suggest.append("Lower Kp by about 20% - it swings around the target.")
        if short:
            w = max(max(by[d]["sse"], sm[d]["sse"]) for d in short)
            issues.append(f"stops {w:.1f} counts short going {names(short)}")
            suggest.append(f"Raise Ki to {max(10, p['ki'] * 2)} (now {p['ki']}): it makes up what the weight leaves short.")
        if flat:
            issues.append(f"runs out of drive going {names(flat)}")
            suggest.append(f"Raise PWMmax by 10-20 (now {p['pwmmax']}).")
        if miss:
            issues.append(f"doesn't get there going {names(miss)}")
            if not flat:
                suggest.append("Raise Kp (or PWMmin) - it stops well short of where it is sent.")
        hold = max(big["fb_std"], small["fb_std"])
        if hold > self._calm(2.0):
            issues.append(f"doesn't hold still (±{hold:.1f} counts)")
            suggest.append("Lower Kp a little, or raise the dead zone by 1 - and check the pot wiring if it glitches.")
        if max(big["pid_std"], small["pid_std"]) > PID_NOISE_MAX:
            issues.append("buzzes while holding")
            suggest.append("Lower Kp or Kd: the pot's noise is being amplified.")
        if big.get("seat_os") is not None and big["seat_os"] >= 25 and big["seat_os"] >= big.get("motor_os", 0) + 20:
            issues.append(f"the seat itself bounces ({big['seat_os']:.0f}% overshoot)")
            suggest.append("More target smoothing softens it; stiffening the frame or seat mounts fixes it.")
        ok = not issues
        if ok:
            self.say("Verdict: these values work " + ("with you in the seat." if seated else "with the seat as it is."))
        else:
            self.say("Verdict: " + "; ".join(issues) + ".")
            for sgg in suggest:
                self.say("Suggestion: " + sgg)
        self.result = {"check": True, "motor": n, "ok": ok, "issues": issues, "suggest": suggest,
                       "values": {k: p[k] for k in ("kp", "ki", "kd", "ks", "pwmmin", "pwmmax", "dz")},
                       "dirs": {"p": _slim(big["dp"]), "m": _slim(big["dm"])},
                       "small": {"p": _slim(small["dp"]), "m": _slim(small["dm"])},
                       "names": {"p": self.dn[1], "m": self.dn[-1]}, "ramp_v": self.ramp_v, "seated": seated}
        self.progress = 100



# --------------------------------------------------------------------------------------------------------------
# Applying a full parameter set (profiles, backup restore) and named profiles
# --------------------------------------------------------------------------------------------------------------

PROFILE_KEYS = [f"{k}{n}" for n in (1, 2, 3) for k in ("Kp", "Ki", "Kd", "Ks", "PWM", "LIM", "DZ")] + \
    ["STATUS", "PWMFREQ", "FILT"]


def _num(v, lo, hi):
    return int(max(lo, min(hi, int(v))))


def apply_params(board, pr):
    """Send a parameter set (same shape as Board.read_params()) to the board. Live only - not saved."""
    if not isinstance(pr, dict) or pr.get("Kp1") is None:
        raise ValueError("no motor settings in it")
    for m in range(3):
        n = m + 1
        for codes, key, lo, hi in (("DEF", "Kp", 0, 65535), ("GHI", "Ki", 0, 65535), ("JKL", "Kd", 0, 65535),
                                   ("MNO", "Ks", 1, 1000)):
            v = pr.get(f"{key}{n}")
            if v is not None:
                board.cmd_word(codes[m], _num(v, lo, hi))
        for codes, key in (("PQR", "PWM"), ("STU", "LIM"), ("VWX", "DZ")):
            v = pr.get(f"{key}{n}")
            if isinstance(v, (list, tuple)) and len(v) == 2:
                board.cmd_pair(codes[m], _num(v[0], 0, 255), _num(v[1], 0, 255))
    st = pr.get("STATUS")
    if isinstance(st, (list, tuple)) and st:
        board.cmd_pair("Z", _num(int(st[0]) >> 4, 1, 10), 0)
    fq = pr.get("PWMFREQ")
    if isinstance(fq, (list, tuple)) and len(fq) == 2:
        board.cmd_pair("~", _num(fq[0], 1, 100), _num(fq[1], 1, 100))
    ft = pr.get("FILT")                      # ignored by firmware older than 1.6
    if isinstance(ft, (list, tuple)) and len(ft) == 2:
        board.cmd_pair("f", _num(ft[0], 0, 8), _num(ft[1], 0, 255))


def summary(p):
    kp = "/".join(str(p.get(f"Kp{n}", "?")) for n in (1, 2, 3))
    ki = "/".join(str(p.get(f"Ki{n}", "?")) for n in (1, 2, 3))
    out = f"Kp {kp}, Ki {ki}"
    ft = p.get("FILT")
    if isinstance(ft, (list, tuple)) and len(ft) == 2:
        out += ", smoothing " + ("off" if not ft[0] else f"{(1 << ft[0]) / 4:g} ms")
        if ft[1]:
            out += f", max {ft[1] * 100}/s"
    return out


def canon(p):
    return {k: p[k] for k in PROFILE_KEYS if k in p}


# --------------------------------------------------------------------------------------------------------------
# Backups: every Save to EEPROM and every bigger change keeps a copy of the board settings on the NAS
# --------------------------------------------------------------------------------------------------------------

class Backups:
    KEEP = {"eeprom": 60, "auto": 40, "manual": 200}

    def __init__(self, data_dir):
        self.path = os.path.join(data_dir, "backups.json")
        self.lock = threading.Lock()
        try:
            with open(self.path) as f:
                self.items = json.load(f)
            if not isinstance(self.items, list):
                self.items = []
        except (OSError, ValueError):
            self.items = []

    def _write(self):
        try:
            os.makedirs(os.path.dirname(self.path), exist_ok=True)
            tmp = self.path + ".tmp"
            with open(tmp, "w") as f:
                json.dump(self.items, f, indent=1)
            os.replace(tmp, self.path)
            return True
        except OSError as e:
            log(f"could not save backups to {self.path}: {e}")
            return False

    def add(self, kind, label, params):
        p = canon(params)
        if p.get("Kp1") is None:
            return None
        with self.lock:
            # an automatic copy identical to the newest backup adds nothing
            if kind == "auto" and self.items and self.items[0]["params"] == p:
                return self.items[0]["id"]
            if kind == "eeprom":
                last = next((b for b in self.items if b["kind"] == "eeprom"), None)
                if last and last["params"] == p and last is self.items[0]:
                    last["when"] = time.strftime("%Y-%m-%d %H:%M:%S")
                    self._write()
                    return last["id"]
            bid = f"{time.time():.3f}".replace(".", "")
            self.items.insert(0, {"id": bid, "when": time.strftime("%Y-%m-%d %H:%M:%S"), "kind": kind,
                                  "label": label[:80], "params": p})
            for k, n in self.KEEP.items():               # retention per kind
                same = [b for b in self.items if b["kind"] == k]
                for old in same[n:]:
                    self.items.remove(old)
            self._write()
            return bid

    def list(self):
        with self.lock:
            return [{"id": b["id"], "when": b["when"], "kind": b["kind"], "label": b["label"],
                     "summary": summary(b["params"]), "params": b["params"]} for b in self.items]

    def get(self, bid):
        with self.lock:
            return next((dict(b) for b in self.items if b["id"] == bid), None)

    def delete(self, bid):
        with self.lock:
            self.items = [b for b in self.items if b["id"] != bid]
            return self._write()


